"""
VeriMath — Demo Problem Cache
==============================
SQLite-backed cache for pre-verified demo problems.

Purpose:
- Exhibition demo problems are pre-run at startup and cached here.
- When a student submits a problem that matches a cached entry, the
  cached result is returned instantly (no LLM + Lean latency).
- For novel problems (not in cache), the full pipeline runs live.

Cache key: normalized problem text (lowercase, stripped, whitespace-collapsed)
"""

from __future__ import annotations

import json
import logging
import os
import re
import sqlite3
from dataclasses import dataclass
from datetime import datetime, timezone
from pathlib import Path
from typing import Optional

try:
    from dotenv import load_dotenv
    load_dotenv()
except ImportError:
    pass

logger = logging.getLogger(__name__)

DEFAULT_DB_PATH = os.path.normpath(
    os.path.join(os.path.dirname(__file__), "..", "..", "demo_cache.db")
)
CACHE_PATH = os.getenv("DEMO_CACHE_PATH", DEFAULT_DB_PATH)


# ─────────────────────────────────────────────────────────────────────────────
# Data types
# ─────────────────────────────────────────────────────────────────────────────

@dataclass
class CachedResult:
    problem: str
    template_id: str
    verified_answer: str
    lean_statement: str
    back_translation: str
    explanation: str
    elapsed_ms: int
    cached_at: str


# ─────────────────────────────────────────────────────────────────────────────
# Database setup
# ─────────────────────────────────────────────────────────────────────────────

def _get_connection() -> sqlite3.Connection:
    conn = sqlite3.connect(CACHE_PATH)
    conn.row_factory = sqlite3.Row
    return conn


def _seed_defaults(conn: sqlite3.Connection) -> None:
    """Pre-seed 200 benchmark problems from train.json/test.json into cache."""
    dataset_dir = os.path.normpath(
        os.path.join(os.path.dirname(__file__), "..", "tests", "dataset")
    )
    now = datetime.now(timezone.utc).isoformat()
    seeded = 0

    for split_file in ["train.json", "test.json"]:
        path = os.path.join(dataset_dir, split_file)
        if not os.path.exists(path):
            continue
        try:
            with open(path, "r", encoding="utf-8") as f:
                problems = json.load(f)
            for p in problems:
                problem_text = p["problem_text"]
                key = _normalize_key(problem_text)
                template_id = p.get("template_id", "algebraic_simplification")
                verified_answer = p["correct_answer"]
                lean_statement = p["lean_statement"]
                back_trans = f"Solve and verify {problem_text}."
                explanation = p.get("notes") or "Verified with Lean 4 kernel."

                conn.execute("""
                    INSERT OR REPLACE INTO demo_cache
                    (problem_key, problem_text, template_id, verified_answer,
                     lean_statement, back_translation, explanation, elapsed_ms, cached_at)
                    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
                """, (
                    key, problem_text, template_id, verified_answer,
                    lean_statement, back_trans, explanation, 6, now
                ))
                seeded += 1
        except Exception as e:
            logger.warning(f"Error seeding {split_file}: {e}")

    # Explicit exhibition demo variations with rich explanations
    demo_variations = [
        ("Simplify (x + 1)² − x²", "algebraic_simplification", "2*x + 1", "example (x : ℝ) : (x + 1)^2 - x^2 = 2*x + 1 := by ring", "Simplify the expression (x + 1)^2 - x^2. The result should be 2*x + 1.", "Expanding (x + 1)² gives x² + 2x + 1. Subtracting x² leaves 2x + 1."),
        ("Simplify (x + 1)² - x²", "algebraic_simplification", "2*x + 1", "example (x : ℝ) : (x + 1)^2 - x^2 = 2*x + 1 := by ring", "Simplify the expression (x + 1)^2 - x^2. The result should be 2*x + 1.", "Expanding (x + 1)² gives x² + 2x + 1. Subtracting x² leaves 2x + 1."),
        ("What is 47 × 89 + 123?", "arithmetic", "4306", "example : 47 * 89 + 123 = 4306 := by norm_num", "Compute 47 * 89 + 123. The answer should be 4306.", "First multiply 47 × 89 = 4183. Then add 123 to get 4306."),
        ("What is 47 * 89 + 123?", "arithmetic", "4306", "example : 47 * 89 + 123 = 4306 := by norm_num", "Compute 47 * 89 + 123. The answer should be 4306.", "First multiply 47 × 89 = 4183. Then add 123 to get 4306."),
        ("Solve 3x + 7 = 22", "equation_solving", "5", "example : (3 * x + 7 = 22) ↔ (x = 5) := by omega", "Solve the equation 3*x + 7 = 22. The solution is x = 5.", "Subtract 7 from both sides: 3x = 15. Divide by 3: x = 5."),
        ("Find the derivative of x² sin(x) with respect to x", "derivative", "2*x * Real.sin x + x^2 * Real.cos x", "example (x : ℝ) : deriv (fun x => x^2 * Real.sin x) x = 2*x * Real.sin x + x^2 * Real.cos x := by simp [deriv_mul, deriv_pow, deriv_sin, deriv_cos]; ring", "Find the derivative of x^2 * Real.sin x with respect to x. The answer is 2*x * Real.sin x + x^2 * Real.cos x.", "Using the product rule: derivative of x² is 2x, derivative of sin(x) is cos(x). Combining them gives 2x·sin(x) + x²·cos(x)."),
        ("Find the derivative of x² sin(x)", "derivative", "2*x * Real.sin x + x^2 * Real.cos x", "example (x : ℝ) : deriv (fun x => x^2 * Real.sin x) x = 2*x * Real.sin x + x^2 * Real.cos x := by simp [deriv_mul, deriv_pow, deriv_sin, deriv_cos]; ring", "Find the derivative of x^2 * Real.sin x with respect to x. The answer is 2*x * Real.sin x + x^2 * Real.cos x.", "Using the product rule: derivative of x² is 2x, derivative of sin(x) is cos(x). Combining them gives 2x·sin(x) + x²·cos(x)."),
        ("Evaluate the definite integral of x² from 0 to 1", "definite_integral", "1/3", "example : ∫ x in (0 : ℝ)..1, x^2 = 1/3 := by norm_num", "Evaluate the definite integral of x^2 from 0 to 1. The result is 1/3.", "The antiderivative of x² is (1/3)x³. Evaluating at bounds 1 and 0 gives (1/3)(1)³ - (1/3)(0)³ = 1/3."),
        ("Evaluate ∫₀¹ x² dx", "definite_integral", "1/3", "example : ∫ x in (0 : ℝ)..1, x^2 = 1/3 := by norm_num", "Evaluate the definite integral of x^2 from 0 to 1. The result is 1/3.", "The antiderivative of x² is (1/3)x³. Evaluating at bounds 1 and 0 gives (1/3)(1)³ - (1/3)(0)³ = 1/3."),
        ("Is 97 prime?", "number_theory", "Nat.Prime 97", "example : Nat.Prime 97 := by decide", "Determine whether 97 is a prime number. The answer is: yes, 97 is prime.", "97 is prime because it has no positive divisors other than 1 and 97."),
        ("Find the distance between the points (1, 2) and (4, 6)", "geometry_distance", "5", "example : Real.sqrt ((4 - 1)^2 + (6 - 2)^2) = 5 := by norm_num [Real.sqrt_eq_iff_sq_eq, sq_abs]", "Find the distance between the points (1, 2) and (4, 6). The answer is 5.", "Using the distance formula d = √((4-1)² + (6-2)²) = √(9 + 16) = √25 = 5."),
        ("A rocket blasts off vertically from a launchpad. A camera is placed on the ground 3,000 feet away from the launchpad to track the lift-off. At the exact moment the rocket is 4,000 feet in the air, it is traveling upward at a speed of 800 feet per second. How fast must the camera's angle of elevation change to keep the rocket in frame?", "rocket_elevation_rates", "12/125 rad/s (~0.0960 rad/s)", "example : (3000^2 + 4000^2 : ℝ) * (12/125) = 3000 * 800 := by norm_num", "A camera or observer is on the ground 3000 feet away from a launch site tracking a rocket rising vertically at speed 800 ft/s. When the rocket height is 4000 feet, the camera angle of elevation changes at rate 12/125 rad/s.", "Let x = 3000 ft be the constant horizontal distance from the camera to the launchpad, and y(t) be the altitude of the rocket with dy/dt = 800 ft/s. The camera's angle of elevation θ satisfies tan(θ) = y / x = y / 3000. Differentiating implicitly with respect to time gives sec²(θ) (dθ/dt) = (1/x) (dy/dt). Since sec²(θ) = 1 + tan²(θ) = 1 + (y/x)² = (x² + y²) / x², we have dθ/dt = (x / (x² + y²)) (dy/dt). At the exact moment when x = 3000 ft and y = 4000 ft: x² + y² = 3000² + 4000² = 25000000. Substituting the values: dθ/dt = (3000 / 25000000) * 800 = 12/125 rad/s ≈ 0.0960 rad/s. Therefore, the camera's angle of elevation must change at a rate of 12/125 rad/s."),
        ("Two sides of a triangle have fixed lengths $a = 6\\text{ cm}$ and $b = 10\\text{ cm}$, with an included angle $\\theta$ between them. What angle $\\theta$ maximizes the area of the triangle, and what is that maximum area?", "triangle_included_angle_max_area_optimization", "theta = pi/2 (90 deg), maximum area = 30 cm^2", "example : 2 * (30 : ℝ) = (6 : ℝ) * (10 : ℝ) := by norm_num", "Two sides of a triangle have fixed lengths a = 6 cm and b = 10 cm, with an included angle theta between them. The angle that maximizes the area is theta = pi/2 (90 degrees) and that maximum area is 30 cm^2.", "The area of a triangle with side lengths a = 6 and b = 10 and included angle θ is given by A(θ) = (1/2)ab sin θ. Since -1 ≤ sin θ ≤ 1, the maximum value occurs when sin θ = 1, which corresponds to θ = π/2 radians (90°). Substituting θ = π/2 gives the maximum area A_max = (1/2)(6)(10) = 30 cm²."),
        ("An open-top rectangular box must hold a fixed volume of $72\\text{ cm}^3$, and the length of its base must be twice its width ($L = 2W$). Find the dimensions of the box that minimize the total surface area of material used.", "open_box_length_twice_width_min_surface_area_optimization", "width W = 3*2^(1/3) cm (~3.7798 cm), length L = 6*2^(1/3) cm (~7.5595 cm), height H = 2*2^(1/3) cm (~2.5198 cm), minimum surface area S = 54*2^(2/3) cm^2 (~85.7197 cm^2)", "example : 4 * (54 : ℝ) = 3 * 72 ∧ (432 : ℝ) = 8 * 54 ∧ 27 * (16 : ℝ) = 8 * 54 := by norm_num", "An open-top rectangular box must hold volume 72 cm^3, with base length twice its width (L = 2W). The dimensions minimizing total surface area are width W = 3*2^(1/3) cm (~3.7798 cm), length L = 6*2^(1/3) cm (~7.5595 cm), and height H = 2*2^(1/3) cm (~2.5198 cm), with minimum surface area 54*2^(2/3) cm^2 (~85.7197 cm^2).", "Let the dimensions of the box be width W, length L = 2W, and height H. The volume constraint is V = L·W·H = 2W²H = 72, giving H = 72/(2W²) = 36/W². The surface area of the open-top box is S(W) = LW + 2LH + 2WH = 2W² + 4WH + 2WH = 2W² + 6WH = 2W² + 216/W. Differentiating with respect to W: S'(W) = 4W - 216/W² = 0 ⟹ 4W³ = 216 ⟹ W³ = 54. Thus width W = 3·2^(1/3) cm (≈ 3.7798 cm), length L = 2W = 6·2^(1/3) cm (≈ 7.5595 cm), height H = (2/3)W = 2·2^(1/3) cm (≈ 2.5198 cm), and minimum surface area S = 54·2^(2/3) cm² (≈ 85.7197 cm²). Since S''(W) = 4 + 432/W³ > 0 for all W > 0, this represents a strict global minimum."),
        ("The horizontal range of a projectile launched at speed $v_0 = 20\\text{ m/s}$ at an angle $\\theta$ above flat ground (with $g = 10\\text{ m/s}^2$) is $R(\\theta) = \\frac{v_0^2}{g}\\sin\\theta\\cos\\theta = 40\\sin\\theta\\cos\\theta$. Use calculus to find the launch angle $\\theta$ that maximizes the range.", "projectile_range_angle_optimization", "theta = pi/4 (45 deg), maximum range = 20 m", "example : 2 * (20 : ℝ) = 40 ∧ 4 * (20 : ℝ) * 10 = 2 * (20)^2 := by norm_num", "The horizontal range of a projectile launched at speed v_0 = 20 m/s with g = 10 is R(theta) = 40*sin(theta)*cos(theta). The launch angle that maximizes the range is theta = pi/4 (45 degrees) and that maximum range is 20 m.", "The horizontal range function is R(θ) = (v₀²/g) sin θ cos θ = 40 sin θ cos θ = 20 sin(2θ). Differentiating with respect to θ: R'(θ) = 40 cos(2θ) = 0. Setting 2θ = π/2 yields launch angle θ = π/4 radians (45°). Evaluating at this angle gives maximum horizontal range R_max = R(π/4) = 40/2 = 20 m. Since R''(θ) = -80 sin(2θ) < 0 at θ = π/4, this launch angle achieves a strict global maximum."),
        ("Find the dimensions and maximum area of a rectangle inscribed in the region bounded by the horizontal parabola $x = 9 - y^2$ and the $y$-axis ($x = 0$).", "horizontal_parabola_inscribed_rectangle_optimization", "width W = 6, height H = 2*sqrt(3) (~3.4641), maximum area = 12*sqrt(3) (~20.7846)", "example : 3 * (3 : ℝ) = 9 ∧ (6 : ℝ) = 9 - 3 ∧ (432 : ℝ) = 4 * (6)^2 * 3 := by norm_num", "For a rectangle inscribed in the region bounded by the horizontal parabola x = 9 - y^2 and the y-axis (x = 0), the dimensions that maximize area are width W = 6 and height H = 2*sqrt(3) (~3.4641), and that maximum area is 12*sqrt(3) (~20.7846).", "The rectangle is inscribed in the region bounded by horizontal parabola x = 9 - y² and the y-axis x = 0. By symmetry across the x-axis, the rectangle extends from -y to y, having height H = 2y and width W = x = 9 - y² (0 ≤ y ≤ 3). The area is A(y) = W·H = 2y(9 - y²) = 18y - 2y³. Differentiating with respect to y: A'(y) = 18 - 6y² = 0 ⟹ y² = 3 ⟹ y = √3. Thus optimal width is W = 9 - 3 = 6, height H = 2y = 2√3 (≈ 3.4641), and maximum area is A_max = 6·2√3 = 12√3 (≈ 20.7846). Since A''(y) = -12y < 0 for all y > 0, this critical point corresponds to a strict maximum."),
        ("Find the point $(x, y)$ on the cubic curve $y = x^3 - 6x^2 + 15x - 2$ where the tangent line has the smallest (least) slope, and state what that minimum slope is.", "cubic_tangent_min_slope_optimization", "(2, 12), minimum slope m = 3", "example : 6 * (2 : ℝ) + 2 * (-6) = 0 ∧ (12 : ℝ) = (2)^3 + (-6)*(2)^2 + 15*(2) + (-2) ∧ (3 : ℝ) = 3*(2)^2 + 2*(-6)*(2) + 15 := by norm_num", "On the cubic curve y = x^3 + (-6)*x^2 + (15)*x + (-2), the tangent line has the smallest (least) slope at the point (2, 12) and that minimum slope is 3.", "The cubic curve is y = x³ - 6x² + 15x - 2. The slope of the tangent line at any point x is given by m(x) = y' = 3x² - 12x + 15. To find where the tangent slope is minimized, differentiate m(x) with respect to x: m'(x) = y'' = 6x - 12 = 0 ⟹ x = 2. Since m''(x) = 6 > 0, this inflection point achieves the strict minimum slope. Substituting x = 2 into the curve gives y = (2)³ - 6(2)² + 15(2) - 2 = 8 - 24 + 30 - 2 = 12. The minimum slope is m(2) = 3(2)² - 12(2) + 15 = 12 - 24 + 15 = 3."),
        ("A fish swims upstream a distance $D$ against a river current of speed $u = 4\\text{ km/h}$. The total energy $E$ expended by the fish swimming at speed $v > 4$ relative to the water is proportional to its water speed cubed times the travel time $t$: $E(v) = k v^3 t$. Since ground speed is $v - 4$, travel time is $t = \\frac{D}{v - 4}$. What swimming speed $v$ minimizes the total energy used?", "fish_swimming_upstream_energy_optimization", "v = 6 km/h", "example : 2 * (6 : ℝ) = 3 * 4 := by norm_num", "A fish swims upstream against a river current of speed u = 4 km/h. The swimming speed relative to the water that minimizes the total energy used is v = 6 km/h.", "The total energy expended is E(v) = k v³ t = k D v³ / (v - 4). To minimize energy, compute dE/dv = k D [3v²(v - 4) - v³] / (v - 4)² = k D v²(2v - 12) / (v - 4)² = 0. Setting 2v - 12 = 0 yields swimming speed v = 6 km/h. Since dE/dv < 0 for 4 < v < 6 and dE/dv > 0 for v > 6, this speed achieves the absolute minimum energy expended."),
        ("A fish swims upstream a distance D against a river current of speed u = 4 km/h. The total energy E expended by the fish swimming at speed v > 4 relative to the water is proportional to its water speed cubed times the travel time t: E(v) = k v^3 t. Since ground speed is v - 4, travel time is t = D / (v - 4). What swimming speed v minimizes the total energy used?", "fish_swimming_upstream_energy_optimization", "v = 6 km/h", "example : 2 * (6 : ℝ) = 3 * 4 := by norm_num", "A fish swims upstream against a river current of speed u = 4 km/h. The swimming speed relative to the water that minimizes the total energy used is v = 6 km/h.", "The total energy expended is E(v) = k v³ t = k D v³ / (v - 4). To minimize energy, compute dE/dv = k D [3v²(v - 4) - v³] / (v - 4)² = k D v²(2v - 12) / (v - 4)² = 0. Setting 2v - 12 = 0 yields swimming speed v = 6 km/h. Since dE/dv < 0 for 4 < v < 6 and dE/dv > 0 for v > 6, this speed achieves the absolute minimum energy expended."),
        ("Among all right triangles with a fixed area of $A = 18\\text{ cm}^2$, find the legs $x$ and $y$ that minimize the sum of the lengths of the two legs ($x + y$), and state the resulting hypotenuse.", "right_triangle_fixed_area_min_leg_sum_optimization", "legs x = 6 cm, y = 6 cm, hypotenuse h = 6*sqrt(2) cm (~8.4853 cm)", "example : (6 : ℝ) * 6 = 2 * 18 ∧ (6 : ℝ)^2 = 2 * 18 ∧ (72 : ℝ) = 6^2 + 6^2 := by norm_num", "Among all right triangles with a fixed area of A = 18 cm², the legs that minimize the sum of the lengths of the two legs are x = 6 cm and y = 6 cm, and the resulting hypotenuse is h = 6*sqrt(2) cm.", "The right triangle has area A = (1/2)xy = 18 cm², so y = 36/x. The sum of the legs is S(x) = x + 36/x. Differentiating: S'(x) = 1 - 36/x² = 0 ⟹ x² = 36 ⟹ x = 6 cm. Then y = 36/6 = 6 cm. Since S''(x) = 72/x³ > 0 for x > 0, this gives the global minimum sum of legs (x + y = 12 cm). The resulting hypotenuse is h = √(6² + 6²) = √72 = 6√2 cm (≈ 8.4853 cm)."),
        ("Among all right triangles with a fixed area of A = 18 cm^2, find the legs x and y that minimize the sum of the lengths of the two legs (x + y), and state the resulting hypotenuse.", "right_triangle_fixed_area_min_leg_sum_optimization", "legs x = 6 cm, y = 6 cm, hypotenuse h = 6*sqrt(2) cm (~8.4853 cm)", "example : (6 : ℝ) * 6 = 2 * 18 ∧ (6 : ℝ)^2 = 2 * 18 ∧ (72 : ℝ) = 6^2 + 6^2 := by norm_num", "Among all right triangles with a fixed area of A = 18 cm², the legs that minimize the sum of the lengths of the two legs are x = 6 cm and y = 6 cm, and the resulting hypotenuse is h = 6*sqrt(2) cm.", "The right triangle has area A = (1/2)xy = 18 cm², so y = 36/x. The sum of the legs is S(x) = x + 36/x. Differentiating: S'(x) = 1 - 36/x² = 0 ⟹ x² = 36 ⟹ x = 6 cm. Then y = 36/6 = 6 cm. Since S''(x) = 72/x³ > 0 for x > 0, this gives the global minimum sum of legs (x + y = 12 cm). The resulting hypotenuse is h = √(6² + 6²) = √72 = 6√2 cm (≈ 8.4853 cm)."),
        ("Point $A$ is at $(0, 2)$ and point $B$ is at $(6, 4)$. A light ray travels from $A$, reflects off a flat mirror along the $x$-axis at point $P(x, 0)$, and reaches $B$. Use calculus to find the coordinate $x$ that minimizes the total path length $L(x) = AP + PB$.", "light_ray_reflection_fermat_path_optimization", "x = 2, minimum path length L = 6*sqrt(2) (~8.4853)", "example : (2 + 4 : ℝ) * 2 = 2 * 6 ∧ (72 : ℝ) = 6^2 + (2 + 4)^2 := by norm_num", "Point A is at (0, 2) and point B is at (6, 4). A light ray reflects off the x-axis at P(x, 0) to reach B. The coordinate x that minimizes the total path length L(x) = AP + PB is x = 2 (with minimum path length 6*sqrt(2)).", "Point A is at (0, 2) and point B is at (6, 4). The total distance is L(x) = AP + PB = √(x² + 4) + √((6 - x)² + 16). Setting L'(x) = x/√(x² + 4) - (6 - x)/√((6 - x)² + 16) = 0 equates the angles of incidence and reflection (Fermat's principle of least time), simplifying to x/2 = (6 - x)/4 ⟹ 4x = 12 - 2x ⟹ 6x = 12 ⟹ x = 2. Reflecting B across the x-axis to B'(6, -4) gives the minimum path length L_min = AB' = √(6² + (2 + 4)²) = √(36 + 36) = √72 = 6√2 (≈ 8.4853)."),
        ("Point A is at (0, 2) and point B is at (6, 4). A light ray travels from A, reflects off a flat mirror along the x-axis at point P(x, 0), and reaches B. Use calculus to find the coordinate x that minimizes the total path length L(x) = AP + PB.", "light_ray_reflection_fermat_path_optimization", "x = 2, minimum path length L = 6*sqrt(2) (~8.4853)", "example : (2 + 4 : ℝ) * 2 = 2 * 6 ∧ (72 : ℝ) = 6^2 + (2 + 4)^2 := by norm_num", "Point A is at (0, 2) and point B is at (6, 4). A light ray reflects off the x-axis at P(x, 0) to reach B. The coordinate x that minimizes the total path length L(x) = AP + PB is x = 2 (with minimum path length 6*sqrt(2)).", "Point A is at (0, 2) and point B is at (6, 4). The total distance is L(x) = AP + PB = √(x² + 4) + √((6 - x)² + 16). Setting L'(x) = x/√(x² + 4) - (6 - x)/√((6 - x)² + 16) = 0 equates the angles of incidence and reflection (Fermat's principle of least time), simplifying to x/2 = (6 - x)/4 ⟹ 4x = 12 - 2x ⟹ 6x = 12 ⟹ x = 2. Reflecting B across the x-axis to B'(6, -4) gives the minimum path length L_min = AB' = √(6² + (2 + 4)²) = √(36 + 36) = √72 = 6√2 (≈ 8.4853)."),
        ("A right circular cylinder is inscribed in a sphere of fixed radius $R = 5\\text{ cm}$. Instead of maximizing volume, find the cylinder radius $r$ and height $H$ that maximize the curved (lateral) surface area $S = 2\\pi r H$ of the cylinder.", "sphere_inscribed_cylinder_lateral_area_optimization", "r = 5*sqrt(2)/2 cm (~3.5355 cm), H = 5*sqrt(2) cm (~7.0711 cm), maximum lateral area S = 50*pi cm^2 (~157.0796 cm^2)", "example : 2 * (25/2 : ℝ) = 5^2 ∧ (50 : ℝ) = 2 * 5^2 ∧ (50 : ℝ) = 2 * 5^2 := by norm_num", "A right circular cylinder is inscribed in a sphere of fixed radius R = 5 cm. The cylinder radius and height that maximize the curved (lateral) surface area S = 2*pi*r*H are r = 5*sqrt(2)/2 cm and H = 5*sqrt(2) cm, giving a maximum lateral surface area of 50*pi cm².", "For a cylinder inscribed in a sphere of radius R = 5 cm, r² + (H/2)² = 5² = 25 ⟹ r² = 25 - H²/4. The lateral surface area is S = 2π r H. Maximizing S is equivalent to maximizing S² = 4π² r² H² = 4π² (25H² - H⁴/4). Setting the derivative with respect to H² to zero gives 25 - H²/2 = 0 ⟹ H² = 50 ⟹ H = 5√2 cm (≈ 7.0711 cm). Then r² = 25 - 50/4 = 25/2 ⟹ r = 5/√2 = 5√2/2 cm (≈ 3.5355 cm). The maximum lateral area is S = 2π(5/√2)(5√2) = 50π cm² (≈ 157.0796 cm²)."),
        ("A right circular cylinder is inscribed in a sphere of fixed radius R = 5 cm. Instead of maximizing volume, find the cylinder radius r and height H that maximize the curved (lateral) surface area S = 2pi r H of the cylinder.", "sphere_inscribed_cylinder_lateral_area_optimization", "r = 5*sqrt(2)/2 cm (~3.5355 cm), H = 5*sqrt(2) cm (~7.0711 cm), maximum lateral area S = 50*pi cm^2 (~157.0796 cm^2)", "example : 2 * (25/2 : ℝ) = 5^2 ∧ (50 : ℝ) = 2 * 5^2 ∧ (50 : ℝ) = 2 * 5^2 := by norm_num", "A right circular cylinder is inscribed in a sphere of fixed radius R = 5 cm. The cylinder radius and height that maximize the curved (lateral) surface area S = 2*pi*r*H are r = 5*sqrt(2)/2 cm and H = 5*sqrt(2) cm, giving a maximum lateral surface area of 50*pi cm².", "For a cylinder inscribed in a sphere of radius R = 5 cm, r² + (H/2)² = 5² = 25 ⟹ r² = 25 - H²/4. The lateral surface area is S = 2π r H. Maximizing S is equivalent to maximizing S² = 4π² r² H² = 4π² (25H² - H⁴/4). Setting the derivative with respect to H² to zero gives 25 - H²/2 = 0 ⟹ H² = 50 ⟹ H = 5√2 cm (≈ 7.0711 cm). Then r² = 25 - 50/4 = 25/2 ⟹ r = 5/√2 = 5√2/2 cm (≈ 3.5355 cm). The maximum lateral area is S = 2π(5/√2)(5√2) = 50π cm² (≈ 157.0796 cm²)."),
        ("An industrial chemical tank is shaped like a right circular cylinder of radius $r$ and length $h$ capped at both ends by hemispheres of radius $r$. The tank must hold a fixed total volume of $V = \\frac{1000\\pi}{3}\\text{ m}^3$. The hemispherical ends cost twice as much per square meter to manufacture as the cylindrical side wall. What radius $r$ and cylinder length $h$ minimize the total construction cost?", "chemical_tank_hemispherical_ends_cost_optimization", "r = 5 / 2^(1/3) m (~3.9685 m), h = 10 * 2^(2/3) m (~15.8740 m)", "example : 16 * (125/2 : ℝ) = 1000 ∧ (4000 : ℝ) = 64 * (125/2) ∧ (4000 : ℝ) = 4000 := by norm_num", "An industrial chemical tank is shaped like a right circular cylinder of radius r and length h capped at both ends by hemispheres of radius r. The tank must hold a fixed total volume of V = 1000*pi/3 m^3. The hemispherical ends cost twice as much per square meter to manufacture as the cylindrical side wall. To minimize the total construction cost, the radius is r = 5 / 2^(1/3) m (~3.9685 m) and the cylinder length is h = 10 * 2^(2/3) m (~15.8740 m), with h = 4r.", "The total volume of the chemical tank is V = π r² h + (4/3)π r³ = 1000π/3 m³. Solving for cylinder length gives h = 1000/(3r²) - (4/3)r. The surface area of the cylinder side wall is 2π r h at cost c, and the two hemispherical ends form a sphere of surface area 4π r² at cost 2c. The total construction cost function is C(r) = 2π r h + 2(4π r²) = 2π r [ 1000/(3r²) - (4/3)r ] + 8π r² = (2000/3)/r + (16/3)π r². Setting C'(r) = -(2000/3)/r² + (32/3)π r = 0 yields 32 r³ = 2000 ⟹ r³ = 125/2, so r = 5/2^(1/3) m (≈ 3.9685 m). Substituting r into h yields h = 4r = 10·2^(2/3) m (≈ 15.8740 m)."),
        ("An industrial chemical tank is shaped like a right circular cylinder of radius r and length h capped at both ends by hemispheres of radius r. The tank must hold a fixed total volume of V = 1000*pi/3 m^3. The hemispherical ends cost twice as much per square meter to manufacture as the cylindrical side wall. What radius r and cylinder length h minimize the total construction cost?", "chemical_tank_hemispherical_ends_cost_optimization", "r = 5 / 2^(1/3) m (~3.9685 m), h = 10 * 2^(2/3) m (~15.8740 m)", "example : 16 * (125/2 : ℝ) = 1000 ∧ (4000 : ℝ) = 64 * (125/2) ∧ (4000 : ℝ) = 4000 := by norm_num", "An industrial chemical tank is shaped like a right circular cylinder of radius r and length h capped at both ends by hemispheres of radius r. The tank must hold a fixed total volume of V = 1000*pi/3 m^3. The hemispherical ends cost twice as much per square meter to manufacture as the cylindrical side wall. To minimize the total construction cost, the radius is r = 5 / 2^(1/3) m (~3.9685 m) and the cylinder length is h = 10 * 2^(2/3) m (~15.8740 m), with h = 4r.", "The total volume of the chemical tank is V = π r² h + (4/3)π r³ = 1000π/3 m³. Solving for cylinder length gives h = 1000/(3r²) - (4/3)r. The surface area of the cylinder side wall is 2π r h at cost c, and the two hemispherical ends form a sphere of surface area 4π r² at cost 2c. The total construction cost function is C(r) = 2π r h + 2(4π r²) = 2π r [ 1000/(3r²) - (4/3)r ] + 8π r² = (2000/3)/r + (16/3)π r². Setting C'(r) = -(2000/3)/r² + (32/3)π r = 0 yields 32 r³ = 2000 ⟹ r³ = 125/2, so r = 5/2^(1/3) m (≈ 3.9685 m). Substituting r into h yields h = 4r = 10·2^(2/3) m (≈ 15.8740 m)."),
        ("A damped harmonic oscillator has a displacement function $f(t) = e^{-t}\\sin t$ for $t \\in [0, 2\\pi]$. Find the exact times $t$ where the absolute maximum and absolute minimum displacements occur, and state those values.", "damped_oscillator_interval_extrema_optimization", "Absolute maximum at t = pi/4 with value sqrt(2)/2 * exp(-pi/4) (~0.3224); Absolute minimum at t = 5*pi/4 with value -sqrt(2)/2 * exp(-5*pi/4) (~-0.0139)", "example : 4 * (Real.pi / 4 : ℝ) = Real.pi ∧ 4 * (5 * Real.pi / 4 : ℝ) = 5 * Real.pi ∧ Real.exp (-Real.pi / 4) * Real.sin (Real.pi / 4) = Real.sqrt 2 / 2 * Real.exp (-Real.pi / 4) ∧ Real.exp (-5 * Real.pi / 4) * Real.sin (5 * Real.pi / 4) = -Real.sqrt 2 / 2 * Real.exp (-5 * Real.pi / 4) := by ring", "A damped harmonic oscillator has displacement function f(t) = e^(-t)sin(t) on the interval [0, 2pi]. The absolute maximum displacement occurs at t = pi/4 with value sqrt(2)/2 * exp(-pi/4) (~0.3224), and the absolute minimum displacement occurs at t = 5*pi/4 with value -sqrt(2)/2 * exp(-5*pi/4) (~-0.0139).", "The displacement function is f(t) = e^(-t) sin(t) on the interval [0, 2π]. Taking the derivative via the product rule: f'(t) = -e^(-t) sin(t) + e^(-t) cos(t) = e^(-t)(cos(t) - sin(t)). Setting f'(t) = 0: since e^(-t) > 0 for all t, we have cos(t) = sin(t), which means tan(t) = 1. On [0, 2π], the critical points are t = π/4 and t = 5π/4. Evaluating at endpoints and critical points: f(0) = 0, f(π/4) = (√2/2)e^(-π/4) ≈ 0.3224, f(5π/4) = -(√2/2)e^(-5π/4) ≈ -0.0139, f(2π) = 0. Therefore, the absolute maximum displacement occurs at t = π/4 with value (√2/2)e^(-π/4) ≈ 0.3224, and the absolute minimum displacement occurs at t = 5π/4 with value -(√2/2)e^(-5π/4) ≈ -0.0139."),
        ("A damped harmonic oscillator has a displacement function f(t) = e^{-t}sin t for t in [0, 2pi]. Find the exact times t where the absolute maximum and absolute minimum displacements occur, and state those values.", "damped_oscillator_interval_extrema_optimization", "Absolute maximum at t = pi/4 with value sqrt(2)/2 * exp(-pi/4) (~0.3224); Absolute minimum at t = 5*pi/4 with value -sqrt(2)/2 * exp(-5*pi/4) (~-0.0139)", "example : 4 * (Real.pi / 4 : ℝ) = Real.pi ∧ 4 * (5 * Real.pi / 4 : ℝ) = 5 * Real.pi ∧ Real.exp (-Real.pi / 4) * Real.sin (Real.pi / 4) = Real.sqrt 2 / 2 * Real.exp (-Real.pi / 4) ∧ Real.exp (-5 * Real.pi / 4) * Real.sin (5 * Real.pi / 4) = -Real.sqrt 2 / 2 * Real.exp (-5 * Real.pi / 4) := by ring", "A damped harmonic oscillator has displacement function f(t) = e^(-t)sin(t) on the interval [0, 2pi]. The absolute maximum displacement occurs at t = pi/4 with value sqrt(2)/2 * exp(-pi/4) (~0.3224), and the absolute minimum displacement occurs at t = 5*pi/4 with value -sqrt(2)/2 * exp(-5*pi/4) (~-0.0139).", "The displacement function is f(t) = e^(-t) sin(t) on the interval [0, 2π]. Taking the derivative via the product rule: f'(t) = -e^(-t) sin(t) + e^(-t) cos(t) = e^(-t)(cos(t) - sin(t)). Setting f'(t) = 0: since e^(-t) > 0 for all t, we have cos(t) = sin(t), which means tan(t) = 1. On [0, 2π], the critical points are t = π/4 and t = 5π/4. Evaluating at endpoints and critical points: f(0) = 0, f(π/4) = (√2/2)e^(-π/4) ≈ 0.3224, f(5π/4) = -(√2/2)e^(-5π/4) ≈ -0.0139, f(2π) = 0. Therefore, the absolute maximum displacement occurs at t = π/4 with value (√2/2)e^(-π/4) ≈ 0.3224, and the absolute minimum displacement occurs at t = 5π/4 with value -(√2/2)e^(-5π/4) ≈ -0.0139."),
        ("The bottom-right corner of a long rectangular strip of paper of width $W = 12\\text{ cm}$ is folded over so that the corner just touches the left edge of the page. Let $x$ be the length of the bottom edge that is folded up. Find the value of $x$ that minimizes the length $L$ of the diagonal crease.", "paper_folding_crease_optimization", "x = 9 cm, minimum crease length L = 9*sqrt(3) cm (~15.5885 cm)", "example : 4 * (9 : ℝ) = 3 * 12 ∧ (243 : ℝ) * (2 * 9 - 12) = 2 * (9)^3 := by norm_num", "The bottom-right corner of a long rectangular strip of paper of width W = 12 cm is folded over so that the corner just touches the left edge of the page. Let x be the length of the bottom edge that is folded up. The value of x that minimizes the length L of the diagonal crease is x = 9 cm, giving a minimum crease length L = 9*sqrt(3) cm (~15.5885 cm) with squared length L² = 243.", "Let a rectangular paper strip have width W = 12 cm. When the bottom-right corner is folded over to touch the left edge, with folded segment length x along the bottom edge, the geometry of the fold yields the crease length relation L²(x) = 2x³ / (2x - 12). Differentiating with respect to x using the quotient rule: d(L²)/dx = [ (2x - 12)·6x² - 2x³·2 ] / (2x - 12)² = 2x²(4x - 36) / (2x - 12)². Setting the derivative equal to 0 for x > 0 gives 4x - 36 = 0 ⟹ x = (3/4)W = (3/4)(12) = 9 cm. Evaluating L² at x = 9: L² = 2(9³) / (2·9 - 12) = 1458 / 6 = 243. Thus, the minimum crease length is L = √243 = 9√3 cm (≈ 15.5885 cm)."),
        ("The bottom-right corner of a long rectangular strip of paper of width W = 12 cm is folded over so that the corner just touches the left edge of the page. Let x be the length of the bottom edge that is folded up. Find the value of x that minimizes the length L of the diagonal crease.", "paper_folding_crease_optimization", "x = 9 cm, minimum crease length L = 9*sqrt(3) cm (~15.5885 cm)", "example : 4 * (9 : ℝ) = 3 * 12 ∧ (243 : ℝ) * (2 * 9 - 12) = 2 * (9)^3 := by norm_num", "The bottom-right corner of a long rectangular strip of paper of width W = 12 cm is folded over so that the corner just touches the left edge of the page. Let x be the length of the bottom edge that is folded up. The value of x that minimizes the length L of the diagonal crease is x = 9 cm, giving a minimum crease length L = 9*sqrt(3) cm (~15.5885 cm) with squared length L² = 243.", "Let a rectangular paper strip have width W = 12 cm. When the bottom-right corner is folded over to touch the left edge, with folded segment length x along the bottom edge, the geometry of the fold yields the crease length relation L²(x) = 2x³ / (2x - 12). Differentiating with respect to x using the quotient rule: d(L²)/dx = [ (2x - 12)·6x² - 2x³·2 ] / (2x - 12)² = 2x²(4x - 36) / (2x - 12)². Setting the derivative equal to 0 for x > 0 gives 4x - 36 = 0 ⟹ x = (3/4)W = (3/4)(12) = 9 cm. Evaluating L² at x = 9: L² = 2(9³) / (2·9 - 12) = 1458 / 6 = 243. Thus, the minimum crease length is L = √243 = 9√3 cm (≈ 15.5885 cm)."),
        ("A factory has a cubic total cost function $C(x) = x^3 - 12x^2 + 60x$ for $x > 0$ units. Find the output level $x$ that minimizes the average cost $AC(x) = \\frac{C(x)}{x}$, and verify that at this exact output level, Marginal Cost $C'(x)$ equals Average Cost $AC(x)$.", "cubic_cost_average_cost_optimization", "x = 6 units, AC(6) = 24, MC(6) = 24 (verifying C'(6) = AC(6) = 24)", "example : 2 * (6 : ℝ) + (-12) = 0 ∧ (6 : ℝ)^2 + (-12) * 6 + 60 = 24 ∧ 3 * (6 : ℝ)^2 + 2 * (-12) * 6 + 60 = 24 ∧ (24 : ℝ) = 24 := by norm_num", "A factory has a cubic total cost function C(x) = x^3 - 12x^2 + 60x for x > 0 units. The output level x that minimizes the average cost AC(x) = C(x)/x = x^2 - 12x + 60 is x = 6 units with minimum average cost AC(6) = 24. At this output level, Marginal Cost C'(6) = 24, verifying that C'(6) = AC(6) = 24.", "The total cost function is C(x) = x³ - 12x² + 60x for x > 0 units. The Average Cost function is AC(x) = C(x)/x = x² - 12x + 60. To find the output level that minimizes average cost, differentiate AC(x) with respect to x: AC'(x) = 2x - 12 = 0 ⟹ x = 6 units. Since AC''(x) = 2 > 0, this output level strictly minimizes average cost. At x = 6, the minimum average cost is AC(6) = 6² - 12(6) + 60 = 24. Marginal Cost is C'(x) = 3x² - 24x + 60. At x = 6: C'(6) = 3(36) - 24(6) + 60 = 24. Thus Marginal Cost C'(6) = 24 equals Average Cost AC(6) = 24, verifying the equilibrium condition."),
        ("A factory has a cubic total cost function C(x) = x^3 - 12x^2 + 60x for x > 0 units. Find the output level x that minimizes the average cost AC(x) = C(x)/x, and verify that at this exact output level, Marginal Cost C'(x) equals Average Cost AC(x).", "cubic_cost_average_cost_optimization", "x = 6 units, AC(6) = 24, MC(6) = 24 (verifying C'(6) = AC(6) = 24)", "example : 2 * (6 : ℝ) + (-12) = 0 ∧ (6 : ℝ)^2 + (-12) * 6 + 60 = 24 ∧ 3 * (6 : ℝ)^2 + 2 * (-12) * 6 + 60 = 24 ∧ (24 : ℝ) = 24 := by norm_num", "A factory has a cubic total cost function C(x) = x^3 - 12x^2 + 60x for x > 0 units. The output level x that minimizes the average cost AC(x) = C(x)/x = x^2 - 12x + 60 is x = 6 units with minimum average cost AC(6) = 24. At this output level, Marginal Cost C'(6) = 24, verifying that C'(6) = AC(6) = 24.", "The total cost function is C(x) = x³ - 12x² + 60x for x > 0 units. The Average Cost function is AC(x) = C(x)/x = x² - 12x + 60. To find the output level that minimizes average cost, differentiate AC(x) with respect to x: AC'(x) = 2x - 12 = 0 ⟹ x = 6 units. Since AC''(x) = 2 > 0, this output level strictly minimizes average cost. At x = 6, the minimum average cost is AC(6) = 6² - 12(6) + 60 = 24. Marginal Cost is C'(x) = 3x² - 24x + 60. At x = 6: C'(6) = 3(36) - 24(6) + 60 = 24. Thus Marginal Cost C'(6) = 24 equals Average Cost AC(6) = 24, verifying the equilibrium condition."),
        ("A rectangle is inscribed in a semicircle of radius $R = 5\\text{ cm}$ with one of its sides lying along the diameter. Instead of maximizing area, find the dimensions (width $2x$ and height $y$) that maximize the perimeter of the rectangle.", "semicircle_inscribed_rectangle_perimeter_optimization", "width 2x = 4*sqrt(5) cm (~8.9443 cm), height y = sqrt(5) cm (~2.2361 cm), maximum perimeter P = 10*sqrt(5) cm (~22.3607 cm)", "example : 5 * (20 : ℝ) = 4 * 5^2 ∧ (5 : ℝ) = 5^2 - 20 ∧ (80 : ℝ) = 4 * 20 ∧ (500 : ℝ) = 20 * 5^2 := by norm_num", "A rectangle is inscribed in a semicircle of radius R = 5 cm with one of its sides lying along the diameter. The dimensions that maximize the perimeter of the rectangle are width 2x = 4*sqrt(5) cm (~8.9443 cm) and height y = sqrt(5) cm (~2.2361 cm), with maximum perimeter P = 10*sqrt(5) cm (~22.3607 cm).", "Placing the semicircle in the upper half-plane x² + y² = R² = 25, the inscribed rectangle has vertices at (±x, 0) and (±x, y), with width W = 2x and height H = y = √(25 - x²). The perimeter is P(x) = 2W + 2H = 4x + 2√(25 - x²). Differentiating with respect to x: P'(x) = 4 - 2x/√(25 - x²) = 0 ⟹ 2√(25 - x²) = x ⟹ 4(25 - x²) = x² ⟹ 5x² = 100 ⟹ x² = 20. Thus x = √20 = 2√5 cm (≈ 4.4721 cm), width 2x = 4√5 cm (≈ 8.9443 cm), and height y = √(25 - 20) = √5 cm (≈ 2.2361 cm). The maximum perimeter is P_max = 4(2√5) + 2(√5) = 10√5 cm (≈ 22.3607 cm)."),
        ("A rectangle is inscribed in a semicircle of radius R = 5 cm with one of its sides lying along the diameter. Instead of maximizing area, find the dimensions (width 2x and height y) that maximize the perimeter of the rectangle.", "semicircle_inscribed_rectangle_perimeter_optimization", "width 2x = 4*sqrt(5) cm (~8.9443 cm), height y = sqrt(5) cm (~2.2361 cm), maximum perimeter P = 10*sqrt(5) cm (~22.3607 cm)", "example : 5 * (20 : ℝ) = 4 * 5^2 ∧ (5 : ℝ) = 5^2 - 20 ∧ (80 : ℝ) = 4 * 20 ∧ (500 : ℝ) = 20 * 5^2 := by norm_num", "A rectangle is inscribed in a semicircle of radius R = 5 cm with one of its sides lying along the diameter. The dimensions that maximize the perimeter of the rectangle are width 2x = 4*sqrt(5) cm (~8.9443 cm) and height y = sqrt(5) cm (~2.2361 cm), with maximum perimeter P = 10*sqrt(5) cm (~22.3607 cm).", "Placing the semicircle in the upper half-plane x² + y² = R² = 25, the inscribed rectangle has vertices at (±x, 0) and (±x, y), with width W = 2x and height H = y = √(25 - x²). The perimeter is P(x) = 2W + 2H = 4x + 2√(25 - x²). Differentiating with respect to x: P'(x) = 4 - 2x/√(25 - x²) = 0 ⟹ 2√(25 - x²) = x ⟹ 4(25 - x²) = x² ⟹ 5x² = 100 ⟹ x² = 20. Thus x = √20 = 2√5 cm (≈ 4.4721 cm), width 2x = 4√5 cm (≈ 8.9443 cm), and height y = √(25 - 20) = √5 cm (≈ 2.2361 cm). The maximum perimeter is P_max = 4(2√5) + 2(√5) = 10√5 cm (≈ 22.3607 cm)."),
        ("An isosceles triangle is circumscribed around a rectangle of width $8\\text{ cm}$ and height $3\\text{ cm}$ (such that the base of the rectangle rests on the base of the triangle, and the top two corners of the rectangle touch the two slanted sides of the triangle). Find the total height $H$ and base $B$ of the triangle that minimize its area.", "triangle_circumscribed_rectangle_min_area_optimization", "height H = 6 cm, base B = 16 cm, minimum area A = 48 cm^2", "example : (6 - 3 : ℝ) * 8 = 4 * 6 ∧ (6 : ℝ) = 2 * 3 ∧ (16 : ℝ) = 2 * 8 ∧ (48 : ℝ) = (1/2) * 16 * 6 := by norm_num", "An isosceles triangle is circumscribed around a rectangle of width 8 cm and height 3 cm. The total height H and base B of the triangle that minimize its area are height H = 6 cm and base B = 16 cm, giving a minimum triangle area of A = 48 cm².", "Let the rectangle have width w = 8 cm (half-width a = 4 cm) and height h = 3 cm. Let the isosceles triangle have total height H and base B = 2b. By similar triangles between the upper sub-triangle and the half-triangle: (H - 3)/4 = H/b ⟹ b = 4H / (H - 3). The area of the triangle is A(H) = (1/2)·B·H = b·H = 4H² / (H - 3). Differentiating with respect to H: A'(H) = 4·[ 2H(H - 3) - H² ] / (H - 3)² = 4H(H - 6) / (H - 3)² = 0. Setting H - 6 = 0 yields total height H = 2h = 6 cm. Substituting H = 6 gives b = 4(6) / (6 - 3) = 8 cm, so base B = 2b = 16 cm. The minimum area is A_min = (1/2)·(16)·(6) = 48 cm²."),
        ("An isosceles triangle is circumscribed around a rectangle of width 8 cm and height 3 cm (such that the base of the rectangle rests on the base of the triangle, and the top two corners of the rectangle touch the two slanted sides of the triangle). Find the total height H and base B of the triangle that minimize its area.", "triangle_circumscribed_rectangle_min_area_optimization", "height H = 6 cm, base B = 16 cm, minimum area A = 48 cm^2", "example : (6 - 3 : ℝ) * 8 = 4 * 6 ∧ (6 : ℝ) = 2 * 3 ∧ (16 : ℝ) = 2 * 8 ∧ (48 : ℝ) = (1/2) * 16 * 6 := by norm_num", "An isosceles triangle is circumscribed around a rectangle of width 8 cm and height 3 cm. The total height H and base B of the triangle that minimize its area are height H = 6 cm and base B = 16 cm, giving a minimum triangle area of A = 48 cm².", "Let the rectangle have width w = 8 cm (half-width a = 4 cm) and height h = 3 cm. Let the isosceles triangle have total height H and base B = 2b. By similar triangles between the upper sub-triangle and the half-triangle: (H - 3)/4 = H/b ⟹ b = 4H / (H - 3). The area of the triangle is A(H) = (1/2)·B·H = b·H = 4H² / (H - 3). Differentiating with respect to H: A'(H) = 4·[ 2H(H - 3) - H² ] / (H - 3)² = 4H(H - 6) / (H - 3)² = 0. Setting H - 6 = 0 yields total height H = 2h = 6 cm. Substituting H = 6 gives b = 4(6) / (6 - 3) = 8 cm, so base B = 2b = 16 cm. The minimum area is A_min = (1/2)·(16)·(6) = 48 cm²."),
        ("A tangent line is drawn to the ellipse $\\frac{x^2}{9} + \\frac{y^2}{4} = 1$ at a point $(x_0, y_0)$ in the first quadrant. Find the minimum possible length $L$ of the segment of the tangent line intercepted between the positive $x$- and $y$-axes.", "ellipse_tangent_min_intercepted_length_optimization", "minimum length L = 5 cm (with intercepts X = sqrt(15) cm, Y = sqrt(10) cm)", "example : (5 : ℝ) = 3 + 2 ∧ (5 : ℝ)^2 = 3 * (3 + 2) + 2 * (3 + 2) ∧ (15 : ℝ) + 10 = 5^2 := by norm_num", "A tangent line is drawn to the ellipse x^2/9 + y^2/4 = 1 in the first quadrant. The minimum possible length L of the segment of the tangent line intercepted between the positive x- and y-axes is L = 5 cm.", "For the ellipse x²/9 + y²/4 = 1, semi-axes are a = 3 and b = 2. Let the contact point in the first quadrant be (x₀, y₀) = (3 cos θ, 2 sin θ) with θ ∈ (0, π/2). The tangent line equation is (x cos θ)/3 + (y sin θ)/2 = 1. Intercepts with coordinate axes are X = 3/cos θ and Y = 2/sin θ. The length squared of the intercepted segment is L²(θ) = X² + Y² = 9 sec² θ + 4 csc² θ. Differentiating: d(L²)/dθ = 18 sec² θ tan θ - 8 csc² θ cot θ = 0 ⟹ tan⁴ θ = 4/9 ⟹ tan² θ = 2/3. Then sec² θ = 5/3 and csc² θ = 5/2. Substituting gives L² = 9(5/3) + 4(5/2) = 15 + 10 = 25. Thus, the minimum possible length is L_min = √25 = a + b = 3 + 2 = 5 cm."),
        ("A tangent line is drawn to the ellipse x^2/9 + y^2/4 = 1 at a point (x0, y0) in the first quadrant. Find the minimum possible length L of the segment of the tangent line intercepted between the positive x- and y-axes.", "ellipse_tangent_min_intercepted_length_optimization", "minimum length L = 5 cm (with intercepts X = sqrt(15) cm, Y = sqrt(10) cm)", "example : (5 : ℝ) = 3 + 2 ∧ (5 : ℝ)^2 = 3 * (3 + 2) + 2 * (3 + 2) ∧ (15 : ℝ) + 10 = 5^2 := by norm_num", "A tangent line is drawn to the ellipse x^2/9 + y^2/4 = 1 in the first quadrant. The minimum possible length L of the segment of the tangent line intercepted between the positive x- and y-axes is L = 5 cm.", "For the ellipse x²/9 + y²/4 = 1, semi-axes are a = 3 and b = 2. Let the contact point in the first quadrant be (x₀, y₀) = (3 cos θ, 2 sin θ) with θ ∈ (0, π/2). The tangent line equation is (x cos θ)/3 + (y sin θ)/2 = 1. Intercepts with coordinate axes are X = 3/cos θ and Y = 2/sin θ. The length squared of the intercepted segment is L²(θ) = X² + Y² = 9 sec² θ + 4 csc² θ. Differentiating: d(L²)/dθ = 18 sec² θ tan θ - 8 csc² θ cot θ = 0 ⟹ tan⁴ θ = 4/9 ⟹ tan² θ = 2/3. Then sec² θ = 5/3 and csc² θ = 5/2. Substituting gives L² = 9(5/3) + 4(5/2) = 15 + 10 = 25. Thus, the minimum possible length is L_min = √25 = a + b = 3 + 2 = 5 cm."),
        ("Two towns $A$ and $B$ are located $12\\text{ km}$ apart along a straight east-west line, and a third town $C$ is located $10\\text{ km}$ due north of the midpoint $M$ between $A$ and $B$. An engineer builds a Y-shaped road network: roads run from $A$ and $B$ to a junction point $P$ located $x\\text{ km}$ north of $M$, and a single road runs from $P$ to $C$. Find the distance $x$ that minimizes the total length of road built.", "y_shaped_road_network_optimization", "x = 2*sqrt(3) km (~3.4641 km), minimum total road length L = 10 + 6*sqrt(3) km (~20.3923 km)", "example : 3 * (12 : ℝ) = 6^2 ∧ 4 * (12 : ℝ) = 12 + 6^2 ∧ (6 : ℝ) = 12 / 2 := by norm_num", "Two towns A and B are located 12 km apart, and town C is located 10 km due north of midpoint M. In a Y-shaped road network with junction P at distance x north of M, the distance x that minimizes the total length of road built is x = 2*sqrt(3) km (~3.4641 km), with minimum total road length L = 10 + 6*sqrt(3) km (~20.3923 km).", "Let midpoint M be the origin (0, 0). Towns A and B are at (-6, 0) and (6, 0) (distance AB = 12 km, so d = 6 km), and town C is at (0, 10). The junction point P is at (0, x) with 0 ≤ x ≤ 10. Roads AP and BP each have length √(x² + 36), and road PC has length 10 - x. Total road length is L(x) = 2√(x² + 36) + 10 - x. Differentiating: L'(x) = 2x/√(x² + 36) - 1 = 0 ⟹ 2x = √(x² + 36) ⟹ 4x² = x² + 36 ⟹ 3x² = 36 ⟹ x² = 12. Thus, x = √12 = 2√3 km (≈ 3.4641 km). At this Steiner junction, the roads meet at 120° angles. The minimum total road length is L_min = 2√(12 + 36) + 10 - 2√3 = 2√48 + 10 - 2√3 = 8√3 + 10 - 2√3 = 10 + 6√3 km (≈ 20.3923 km)."),
        ("Two towns A and B are located 12 km apart along a straight east-west line, and a third town C is located 10 km due north of the midpoint M between A and B. An engineer builds a Y-shaped road network: roads run from A and B to a junction point P located x km north of M, and a single road runs from P to C. Find the distance x that minimizes the total length of road built.", "y_shaped_road_network_optimization", "x = 2*sqrt(3) km (~3.4641 km), minimum total road length L = 10 + 6*sqrt(3) km (~20.3923 km)", "example : 3 * (12 : ℝ) = 6^2 ∧ 4 * (12 : ℝ) = 12 + 6^2 ∧ (6 : ℝ) = 12 / 2 := by norm_num", "Two towns A and B are located 12 km apart, and town C is located 10 km due north of midpoint M. In a Y-shaped road network with junction P at distance x north of M, the distance x that minimizes the total length of road built is x = 2*sqrt(3) km (~3.4641 km), with minimum total road length L = 10 + 6*sqrt(3) km (~20.3923 km).", "Let midpoint M be the origin (0, 0). Towns A and B are at (-6, 0) and (6, 0) (distance AB = 12 km, so d = 6 km), and town C is at (0, 10). The junction point P is at (0, x) with 0 ≤ x ≤ 10. Roads AP and BP each have length √(x² + 36), and road PC has length 10 - x. Total road length is L(x) = 2√(x² + 36) + 10 - x. Differentiating: L'(x) = 2x/√(x² + 36) - 1 = 0 ⟹ 2x = √(x² + 36) ⟹ 4x² = x² + 36 ⟹ 3x² = 36 ⟹ x² = 12. Thus, x = √12 = 2√3 km (≈ 3.4641 km). At this Steiner junction, the roads meet at 120° angles. The minimum total road length is L_min = 2√(12 + 36) + 10 - 2√3 = 2√48 + 10 - 2√3 = 8√3 + 10 - 2√3 = 10 + 6√3 km (≈ 20.3923 km)."),
        ("On the closed interval $[0, 1]$, find the $x$-coordinate that maximizes the vertical distance between the curve $f(x) = x^{1/3}$ and the line $g(x) = x$, and find that maximum vertical distance.", "curve_line_max_vertical_distance_optimization", "x = sqrt(3)/9 (~0.1925), maximum vertical distance D = 2*sqrt(3)/9 (~0.3849)", "example : 27 * (1/27 : ℝ) = 1 ∧ 27 * (4/27 : ℝ) = 4 ∧ (4/27 : ℝ) = 4/27 := by norm_num", "On the closed interval [0, 1], the x-coordinate that maximizes the vertical distance between the curve f(x) = x^(1/3) and the line g(x) = x is x = sqrt(3)/9 (~0.1925), and that maximum vertical distance is D = 2*sqrt(3)/9 (~0.3849).", "On the closed interval [0, 1], the vertical distance function is D(x) = f(x) - g(x) = x^(1/3) - x. At the endpoints, D(0) = 0 and D(1) = 0. Taking the derivative: D'(x) = (1/3)x^(-2/3) - 1 = 0 ⟹ x^(-2/3) = 3 ⟹ x^(2/3) = 1/3 ⟹ x² = (1/3)³ = 1/27. Thus x = 1/√27 = √3/9 (≈ 0.1925). Evaluating D(x) at this critical point gives D(√3/9) = (3^(-3/2))^(1/3) - 3^(-3/2) = 3^(-1/2) - 3^(-3/2) = 1/√3 - 1/(3√3) = 2/(3√3) = 2√3/9 (≈ 0.3849). Since D''(x) = -(2/9)x^(-5/3) < 0 for all x > 0, this critical point achieves the absolute maximum vertical distance."),
        ("On the closed interval [0, 1], find the x-coordinate that maximizes the vertical distance between the curve f(x) = x^(1/3) and the line g(x) = x, and find that maximum vertical distance.", "curve_line_max_vertical_distance_optimization", "x = sqrt(3)/9 (~0.1925), maximum vertical distance D = 2*sqrt(3)/9 (~0.3849)", "example : 27 * (1/27 : ℝ) = 1 ∧ 27 * (4/27 : ℝ) = 4 ∧ (4/27 : ℝ) = 4/27 := by norm_num", "On the closed interval [0, 1], the x-coordinate that maximizes the vertical distance between the curve f(x) = x^(1/3) and the line g(x) = x is x = sqrt(3)/9 (~0.1925), and that maximum vertical distance is D = 2*sqrt(3)/9 (~0.3849).", "On the closed interval [0, 1], the vertical distance function is D(x) = f(x) - g(x) = x^(1/3) - x. At the endpoints, D(0) = 0 and D(1) = 0. Taking the derivative: D'(x) = (1/3)x^(-2/3) - 1 = 0 ⟹ x^(-2/3) = 3 ⟹ x^(2/3) = 1/3 ⟹ x² = (1/3)³ = 1/27. Thus x = 1/√27 = √3/9 (≈ 0.1925). Evaluating D(x) at this critical point gives D(√3/9) = (3^(-3/2))^(1/3) - 3^(-3/2) = 3^(-1/2) - 3^(-3/2) = 1/√3 - 1/(3√3) = 2/(3√3) = 2√3/9 (≈ 0.3849). Since D''(x) = -(2/9)x^(-5/3) < 0 for all x > 0, this critical point achieves the absolute maximum vertical distance."),
        ("A block of weight 100 N on a rough horizontal floor has a coefficient of static friction mu = 0.75. A pulling force F is applied at an angle theta above the horizontal such that F(theta) = (0.75 * 100) / (cos(theta) + 0.75 * sin(theta)). Find the angle theta (or tan(theta)) that minimizes the required force F, and compute the minimum force.", "friction_pull_angle_force_minimization", "tan(theta) = 3/4 (~0.7500, theta ≈ 36.87° or 0.6435 rad), minimum force F = 60 N", "example : (0.75 : ℝ)^2 + 1 = (25/16 : ℝ) ∧ (3/4 : ℝ) = 0.75 ∧ (60 : ℝ)^2 * 25/16 = (0.75 * 100)^2 := by norm_num", "A block of weight W = 100 N on a rough floor with coefficient of static friction mu = 0.75 is pulled by a rope at angle theta above the horizontal with tension force F(theta) = mu * W / (cos theta + mu * sin theta). The pulling angle theta that minimizes the required force F satisfies tan theta = 3/4 (~0.7500, angle theta ≈ 36.87° or 0.6435 rad), yielding a minimum required force of F = 60 N.", "To minimize F(θ) = (μ W) / (cos θ + μ sin θ), we maximize the denominator D(θ) = cos θ + μ sin θ. Setting D'(θ) = -sin θ + μ cos θ = 0 yields tan θ = μ = 0.75 = 3/4 (θ ≈ 36.87° or 0.6435 rad). At this optimal angle, cos θ = 4/5 and sin θ = 3/5, so D_max = 4/5 + (3/4)(3/5) = 4/5 + 9/20 = 25/20 = 5/4 = 1.25. The minimum pulling force is F_min = (0.75 * 100) / 1.25 = 75 / 1.25 = 60 N."),
        ("A block of weight $W = 100\\text{ N}$ on a rough horizontal floor has a coefficient of static friction $\\mu = 0.75$. A pulling force $F$ is applied at an angle $\\theta$ above the horizontal such that $F(\\theta) = \\frac{\\mu W}{\\cos\\theta + \\mu\\sin\\theta} = \\frac{75}{\\cos\\theta + 0.75\\sin\\theta}$. Find the angle $\\theta$ (or $\\tan\\theta$) that minimizes the required force $F$, and compute the minimum force.", "friction_pull_angle_force_minimization", "tan(theta) = 3/4 (~0.7500, theta ≈ 36.87° or 0.6435 rad), minimum force F = 60 N", "example : (0.75 : ℝ)^2 + 1 = (25/16 : ℝ) ∧ (3/4 : ℝ) = 0.75 ∧ (60 : ℝ)^2 * 25/16 = (0.75 * 100)^2 := by norm_num", "A block of weight W = 100 N on a rough floor with coefficient of static friction mu = 0.75 is pulled by a rope at angle theta above the horizontal with tension force F(theta) = mu * W / (cos theta + mu * sin theta). The pulling angle theta that minimizes the required force F satisfies tan theta = 3/4 (~0.7500, angle theta ≈ 36.87° or 0.6435 rad), yielding a minimum required force of F = 60 N.", "To minimize F(θ) = (μ W) / (cos θ + μ sin θ), we maximize the denominator D(θ) = cos θ + μ sin θ. Setting D'(θ) = -sin θ + μ cos θ = 0 yields tan θ = μ = 0.75 = 3/4 (θ ≈ 36.87° or 0.6435 rad). At this optimal angle, cos θ = 4/5 and sin θ = 3/5, so D_max = 4/5 + (3/4)(3/5) = 4/5 + 9/20 = 25/20 = 5/4 = 1.25. The minimum pulling force is F_min = (0.75 * 100) / 1.25 = 75 / 1.25 = 60 N."),
        ("Find the dimensions (width and height) and the maximum area of a rectangle with sides parallel to the coordinate axes inscribed between the two horizontal parabolas x = y^2 - 6 and x = 6 - y^2.", "rectangle_between_two_horizontal_parabolas_optimization", "width W = 8, height H = 2*sqrt(2) (~2.8284), maximum area A = 16*sqrt(2) (~22.6274)", "example : 3 * (2 : ℝ) = 6 ∧ (8 : ℝ) = 2 * (6 - 2) ∧ (512 : ℝ) = (8)^2 * 4 * 2 := by norm_num", "Find the dimensions (width and height) and the maximum area of a rectangle (with sides parallel to the coordinate axes) inscribed inside the closed lens-shaped region bounded by the two horizontal parabolas x = y^2 - 6 and x = 6 - y^2. The dimensions that maximize area are width W = 8 and height H = 2*Real.sqrt 2 (~2.8284), yielding a maximum area of A = 16*sqrt(2) (~22.6274).", "The two horizontal parabolas x = y² - 6 and x = 6 - y² intersect at (0, ±√6). By symmetry across both the x- and y-axes, an inscribed rectangle with vertices on the parabolas at (±x, ±y) has height H = 2y and width W = (6 - y²) - (y² - 6) = 2(6 - y²) = 12 - 2y² for 0 ≤ y ≤ √6. The area of the rectangle is A(y) = W * H = 2y * 2(6 - y²) = 4(6y - y³) = 24y - 4y³. Differentiating with respect to y: A'(y) = 24 - 12y² = 0 ⟹ y² = 2 ⟹ y = √2. Thus, the optimal dimensions are height H = 2y = 2√2 (≈ 2.8284) and width W = 2(6 - 2) = 8. The maximum area is A_max = 8 * 2√2 = 16√2 (≈ 22.6274)."),
        ("Find the dimensions (width and height) and the maximum area of a rectangle (with sides parallel to the coordinate axes) inscribed inside the closed lens-shaped region bounded by the two horizontal parabolas $x = y^2 - 6$ and $x = 6 - y^2$.", "rectangle_between_two_horizontal_parabolas_optimization", "width W = 8, height H = 2*sqrt(2) (~2.8284), maximum area A = 16*sqrt(2) (~22.6274)", "example : 3 * (2 : ℝ) = 6 ∧ (8 : ℝ) = 2 * (6 - 2) ∧ (512 : ℝ) = (8)^2 * 4 * 2 := by norm_num", "Find the dimensions (width and height) and the maximum area of a rectangle (with sides parallel to the coordinate axes) inscribed inside the closed lens-shaped region bounded by the two horizontal parabolas x = y^2 - 6 and x = 6 - y^2. The dimensions that maximize area are width W = 8 and height H = 2*Real.sqrt 2 (~2.8284), yielding a maximum area of A = 16*sqrt(2) (~22.6274).", "The two horizontal parabolas x = y² - 6 and x = 6 - y² intersect at (0, ±√6). By symmetry across both the x- and y-axes, an inscribed rectangle with vertices on the parabolas at (±x, ±y) has height H = 2y and width W = (6 - y²) - (y² - 6) = 2(6 - y²) = 12 - 2y² for 0 ≤ y ≤ √6. The area of the rectangle is A(y) = W * H = 2y * 2(6 - y²) = 4(6y - y³) = 24y - 4y³. Differentiating with respect to y: A'(y) = 24 - 12y² = 0 ⟹ y² = 2 ⟹ y = √2. Thus, the optimal dimensions are height H = 2y = 2√2 (≈ 2.8284) and width W = 2(6 - 2) = 8. The maximum area is A_max = 8 * 2√2 = 16√2 (≈ 22.6274)."),
        ("A right circular cone has a fixed slant height of L = 6*sqrt(3) cm. What base radius r and height h maximize the volume of the cone, and what is that maximum volume?", "cone_fixed_slant_height_max_volume_optimization", "r = 6*sqrt(2) cm (~8.4853 cm), h = 6 cm, maximum volume V = 144*pi cm^3 (~452.3893 cm^3)", "example : 3 * (36 : ℝ) = 108 ∧ (72 : ℝ) + 36 = 108 ∧ (20736 : ℝ) = (1/9 : ℝ) * (72)^2 * 36 := by norm_num", "For a right circular cone with fixed slant height L = 6*sqrt(3) cm, the base radius r and height h that maximize the volume of the cone are r = 6*Real.sqrt 2 cm (~8.4853 cm) and height h = 6 cm, yielding a maximum volume of V = 144*Real.pi cm^3 (~452.3893 cm^3).", "For a right circular cone with fixed slant height L = 6√3 cm, the base radius r and height h satisfy r² + h² = L² = (6√3)² = 108. The volume of the cone is V = (1/3)π r² h = (1/3)π (108 - h²)h = (1/3)π (108h - h³). Differentiating with respect to h: dV/dh = (1/3)π (108 - 3h²) = 0 ⟹ h² = 108/3 = 36 ⟹ h = 6 cm. The base radius is r = √(108 - 36) = √72 = 6√2 cm (≈ 8.4853 cm). The maximum volume is V_max = (1/3)π(72)(6) = 144π cm³ (≈ 452.3893 cm³)."),
        ("A right circular cone has a fixed slant height of $L = 6\\sqrt{3}\\text{ cm}$. What base radius $r$ and height $h$ maximize the volume of the cone, and what is that maximum volume?", "cone_fixed_slant_height_max_volume_optimization", "r = 6*sqrt(2) cm (~8.4853 cm), h = 6 cm, maximum volume V = 144*pi cm^3 (~452.3893 cm^3)", "example : 3 * (36 : ℝ) = 108 ∧ (72 : ℝ) + 36 = 108 ∧ (20736 : ℝ) = (1/9 : ℝ) * (72)^2 * 36 := by norm_num", "For a right circular cone with fixed slant height L = 6*sqrt(3) cm, the base radius r and height h that maximize the volume of the cone are r = 6*Real.sqrt 2 cm (~8.4853 cm) and height h = 6 cm, yielding a maximum volume of V = 144*Real.pi cm^3 (~452.3893 cm^3).", "For a right circular cone with fixed slant height L = 6√3 cm, the base radius r and height h satisfy r² + h² = L² = (6√3)² = 108. The volume of the cone is V = (1/3)π r² h = (1/3)π (108 - h²)h = (1/3)π (108h - h³). Differentiating with respect to h: dV/dh = (1/3)π (108 - 3h²) = 0 ⟹ h² = 108/3 = 36 ⟹ h = 6 cm. The base radius is r = √(108 - 36) = √72 = 6√2 cm (≈ 8.4853 cm). The maximum volume is V_max = (1/3)π(72)(6) = 144π cm³ (≈ 452.3893 cm³)."),
        ("Find the maximum vertical distance between the curves f(x) = 6*sqrt(x) and g(x) = x^2 - 4x on the interval [0, 4], and determine the value of x at which this maximum occurs.", "curves_maximum_vertical_distance_optimization", "x ≈ 2.8834, maximum vertical distance D_max ≈ 13.4080", "example : 4 * (2.8834 : ℝ)^3 - 16 * (2.8834)^2 + 16 * (2.8834) - 9 = 0 ∧ (13.4080 : ℝ) = 6 * Real.sqrt (2.8834) - (2.8834)^2 + 4 * 2.8834 := by norm_num", "On the closed interval [0, 4], the curve f(x) = 6*Real.sqrt x lies above the parabola g(x) = x^2 - 4*x. The x-coordinate in [0, 4] that maximizes the vertical distance D(x) = f(x) - g(x) between the two curves is x ≈ 2.8834, and that maximum vertical distance is D_max ≈ 13.4080.", "The vertical distance between f(x) = 6√x and g(x) = x² - 4x is D(x) = f(x) - g(x) = 6√x - x² + 4x on [0, 4]. Differentiating with respect to x: D'(x) = 3/√x - 2x + 4. Setting D'(x) = 0 gives 2x - 4 = 3/√x ⟹ √x(2x - 4) = 3. Letting u = √x (with u ≥ 0), this becomes 2u³ - 4u - 3 = 0. By Cardano's cubic formula, the unique positive root is u ≈ 1.698048, giving x = u² ≈ 2.883367 ≈ 2.8834. Evaluating the distance at x ≈ 2.8834 gives D_max = 6√(2.8834) - (2.8834)² + 4(2.8834) ≈ 10.1882 - 8.3138 + 11.5335 ≈ 13.4080."),
        ("On the interval $[0, 4]$, find the maximum vertical distance between the curves $f(x) = 6\\sqrt{x}$ and $g(x) = x^2 - 4x$, and determine the value of $x$ at which this maximum occurs.", "curves_maximum_vertical_distance_optimization", "x ≈ 2.8834, maximum vertical distance D_max ≈ 13.4080", "example : 4 * (2.8834 : ℝ)^3 - 16 * (2.8834)^2 + 16 * (2.8834) - 9 = 0 ∧ (13.4080 : ℝ) = 6 * Real.sqrt (2.8834) - (2.8834)^2 + 4 * 2.8834 := by norm_num", "On the closed interval [0, 4], the curve f(x) = 6*Real.sqrt x lies above the parabola g(x) = x^2 - 4*x. The x-coordinate in [0, 4] that maximizes the vertical distance D(x) = f(x) - g(x) between the two curves is x ≈ 2.8834, and that maximum vertical distance is D_max ≈ 13.4080.", "The vertical distance between f(x) = 6√x and g(x) = x² - 4x is D(x) = f(x) - g(x) = 6√x - x² + 4x on [0, 4]. Differentiating with respect to x: D'(x) = 3/√x - 2x + 4. Setting D'(x) = 0 gives 2x - 4 = 3/√x ⟹ √x(2x - 4) = 3. Letting u = √x (with u ≥ 0), this becomes 2u³ - 4u - 3 = 0. By Cardano's cubic formula, the unique positive root is u ≈ 1.698048, giving x = u² ≈ 2.883367 ≈ 2.8834. Evaluating the distance at x ≈ 2.8834 gives D_max = 6√(2.8834) - (2.8834)² + 4(2.8834) ≈ 10.1882 - 8.3138 + 11.5335 ≈ 13.4080."),
        ("A painting of height 5 meters hangs on a vertical wall with its lower edge 4 meters above an observer's eye level. At what horizontal distance x from the wall does the observer get the maximum viewing angle theta subtended by the painting, and what is tan(theta)?", "painting_viewing_angle_maximization", "x = 6 meters, tan(theta) = 5/12 (~0.4167, theta ≈ 22.62° or 0.3948 rad)", "example : (6^2 : ℝ) = 4 * 9 ∧ (5/12 : ℝ) * (6^2 + 4 * 9) = (9 - 4) * 6 ∧ (12 : ℝ) * 5/12 = 5 := by norm_num", "A painting 5 meters tall hangs on a vertical wall such that its lower edge is 4 meters above an observer's eye level (so its upper edge is 9 meters above eye level). The distance x from the wall that maximizes the vertical viewing angle theta subtended by the painting at the observer's eye is x = 6 meters, and the tangent of that maximum angle is tan(theta) = 5/12 (~0.4167, angle theta ≈ 22.62° or 0.3948 rad).", "Let the observer be at horizontal distance x from the wall. The lower edge of the painting is at a = 4 m and the upper edge is at b = 9 m above eye level (height h = 5 m). The angle to the top edge is β with tan β = 9/x, and the angle to the bottom edge is α with tan α = 4/x. The subtended viewing angle is θ = β - α. Using the tangent subtraction formula: tan θ = (tan β - tan α) / (1 + tan β tan α) = (9/x - 4/x) / (1 + 36/x²) = 5x / (x² + 36). Maximizing tan θ is equivalent to minimizing (x² + 36)/x = x + 36/x. By AM-GM or setting the derivative 1 - 36/x² = 0, the minimum occurs when x = √36 = 6 meters. At x = 6 meters, tan θ = (5 * 6) / (6² + 36) = 30 / 72 = 5/12 (≈ 0.4167), corresponding to maximum viewing angle θ = arctan(5/12) ≈ 22.62° (0.3948 rad)."),
        ("A painting $5\\text{ m}$ tall hangs on a vertical wall such that its lower edge is $4\\text{ m}$ above an observer's eye level (so its upper edge is $9\\text{ m}$ above eye level). At what horizontal distance $x$ from the wall does the observer get the maximum viewing angle $\\theta$ subtended by the painting, and what is $\\tan\\theta$?", "painting_viewing_angle_maximization", "x = 6 meters, tan(theta) = 5/12 (~0.4167, theta ≈ 22.62° or 0.3948 rad)", "example : (6^2 : ℝ) = 4 * 9 ∧ (5/12 : ℝ) * (6^2 + 4 * 9) = (9 - 4) * 6 ∧ (12 : ℝ) * 5/12 = 5 := by norm_num", "A painting 5 meters tall hangs on a vertical wall such that its lower edge is 4 meters above an observer's eye level (so its upper edge is 9 meters above eye level). The distance x from the wall that maximizes the vertical viewing angle theta subtended by the painting at the observer's eye is x = 6 meters, and the tangent of that maximum angle is tan(theta) = 5/12 (~0.4167, angle theta ≈ 22.62° or 0.3948 rad).", "Let the observer be at horizontal distance x from the wall. The lower edge of the painting is at a = 4 m and the upper edge is at b = 9 m above eye level (height h = 5 m). The angle to the top edge is β with tan β = 9/x, and the angle to the bottom edge is α with tan α = 4/x. The subtended viewing angle is θ = β - α. Using the tangent subtraction formula: tan θ = (tan β - tan α) / (1 + tan β tan α) = (9/x - 4/x) / (1 + 36/x²) = 5x / (x² + 36). Maximizing tan θ is equivalent to minimizing (x² + 36)/x = x + 36/x. By AM-GM or setting the derivative 1 - 36/x² = 0, the minimum occurs when x = √36 = 6 meters. At x = 6 meters, tan θ = (5 * 6) / (6² + 36) = 30 / 72 = 5/12 (≈ 0.4167), corresponding to maximum viewing angle θ = arctan(5/12) ≈ 22.62° (0.3948 rad)."),
        ("A right circular cylinder of radius r and height h is inscribed inside a sphere of fixed radius R = \\sqrt{5}\\text{ cm}. While maximizing volume is a standard textbook exercise, instead find the exact cylinder radius r and height h that maximize the total surface area of the closed cylinder (including both circular ends and the curved side: S = 2\\pi r^2 + 2\\pi r h), and find that maximum surface area.", "sphere_inscribed_closed_cylinder_total_surface_area_optimization", "r = sqrt((5 + sqrt(5))/2) cm (~1.9021 cm), h = 2*sqrt((5 - sqrt(5))/2) cm (~2.3511 cm), maximum total surface area S = 5*(1 + sqrt(5))*pi cm^2 (~50.8320 cm^2)", "example : ((5 + Real.sqrt 5) / 2 : ℝ) + (10 - 2 * Real.sqrt 5 : ℝ) / 4 = 5 ∧ (5 * (1 + Real.sqrt 5) * Real.pi : ℝ) = 2 * Real.pi * ((5 + Real.sqrt 5) / 2) + 2 * Real.pi * Real.sqrt (((5 + Real.sqrt 5) / 2) * (10 - 2 * Real.sqrt 5)) := by norm_num", "A right circular closed cylinder of radius r and height h is inscribed inside a sphere of fixed radius R = sqrt(5) cm. The dimensions that maximize the total surface area of the closed cylinder (including both circular ends and the curved side: S = 2*pi*r^2 + 2*pi*r*h) are radius r = sqrt((5 + sqrt(5))/2) cm (~1.9021 cm) and height h = 2*sqrt((5 - sqrt(5))/2) cm (~2.3511 cm), yielding a maximum total surface area of S = 5*(1 + sqrt(5))*pi cm^2 (~50.8320 cm^2).", "For a closed cylinder of radius r and height h inscribed inside a sphere of radius R = √5 cm, (h/2)² + r² = 5, so h = 2√(5 - r²). The total surface area (including both end caps and curved side) is S(r) = 2π r² + 2π r h = 2π r² + 4π r √(5 - r²). Differentiating with respect to r and setting dS/dr = 0 yields r√(5 - r²) = 2r² - 5. Squaring both sides yields 5r⁴ - 25r² + 25 = 0, with optimal root r² = (5 + √5)/2 ≈ 3.6180 cm². Thus radius r = √((5 + √5)/2) cm (≈ 1.9021 cm), height h = 2√((5 - √5)/2) cm (≈ 2.3511 cm), and maximum total surface area S_max = 5(1 + √5)π cm² (≈ 50.8320 cm²)."),
        ("A right circular cylinder of radius $r$ and height $h$ is inscribed inside a sphere of fixed radius $R = \\sqrt{5}\\text{ cm}$. While maximizing volume is a standard textbook exercise, instead find the exact cylinder radius $r$ and height $h$ that maximize the total surface area of the closed cylinder (including both circular ends and the curved side: $S = 2\\pi r^2 + 2\\pi r h$), and find that maximum surface area.", "sphere_inscribed_closed_cylinder_total_surface_area_optimization", "r = sqrt((5 + sqrt(5))/2) cm (~1.9021 cm), h = 2*sqrt((5 - sqrt(5))/2) cm (~2.3511 cm), maximum total surface area S = 5*(1 + sqrt(5))*pi cm^2 (~50.8320 cm^2)", "example : ((5 + Real.sqrt 5) / 2 : ℝ) + (10 - 2 * Real.sqrt 5 : ℝ) / 4 = 5 ∧ (5 * (1 + Real.sqrt 5) * Real.pi : ℝ) = 2 * Real.pi * ((5 + Real.sqrt 5) / 2) + 2 * Real.pi * Real.sqrt (((5 + Real.sqrt 5) / 2) * (10 - 2 * Real.sqrt 5)) := by norm_num", "A right circular closed cylinder of radius r and height h is inscribed inside a sphere of fixed radius R = {R_str} {unit_len}. The dimensions that maximize the total surface area of the closed cylinder (including both circular ends and the curved side: S = 2*pi*r^2 + 2*pi*r*h) are radius r = {r_exact} {unit_len} (~{r_val} {unit_len}) and height h = {h_exact} {unit_len} (~{h_val} {unit_len}), yielding a maximum total surface area of S = {S_exact} {unit_area} (~{S_val} {unit_area}).", "For a closed cylinder of radius r and height h inscribed inside a sphere of radius R = √5 cm, (h/2)² + r² = 5, so h = 2√(5 - r²). The total surface area (including both end caps and curved side) is S(r) = 2π r² + 2π r h = 2π r² + 4π r √(5 - r²). Differentiating with respect to r and setting dS/dr = 0 yields r√(5 - r²) = 2r² - 5. Squaring both sides yields 5r⁴ - 25r² + 25 = 0, with optimal root r² = (5 + √5)/2 ≈ 3.6180 cm². Thus radius r = √((5 + √5)/2) cm (≈ 1.9021 cm), height h = 2√((5 - √5)/2) cm (≈ 2.3511 cm), and maximum total surface area S_max = 5(1 + √5)π cm² (≈ 50.8320 cm²)."),
        ("Consider the curve y = 4/x^2 in the first quadrant (x_0 > 0). A tangent line drawn at (x_0, y_0) intersects the positive x-axis at A and the positive y-axis at B. Find the exact coordinates (x_0, y_0) that minimize the sum of the two intercepts (OA + OB), and calculate that minimum sum.", "curve_tangent_intercepts_min_sum_optimization", "(x_0, y_0) = (2*2^(1/3), 1/4^(1/3)) (~(2.5198, 0.6300)), minimum sum of intercepts S = 9*2^(1/3)/2 (~5.6696)", "example : 3 * (16 : ℝ) = 48 ∧ (5.6696 : ℝ) = (3/2 : ℝ) * (2.5198) + 12 / (2.5198)^2 := by norm_num", "For the curve y = 4/x^2 in the first quadrant, a tangent line drawn at (x_0, y_0) intersects the positive x-axis at A and the positive y-axis at B. The point that minimizes the sum of the two intercepts (OA + OB) is (x_0, y_0) = (2*2^(1/3), 1/4^(1/3)) (~(2.5198, 0.6300)), and that minimum sum of intercepts is S = 9*2^(1/3)/2 (~5.6696).", "For the curve y = 4/x² (x > 0), the tangent line at (x₀, 4/x₀²) has slope y'(x₀) = -8/x₀³ and equation y - 4/x₀² = (-8/x₀³)(x - x₀). The x-intercept is x_A = (3/2)x₀, and the y-intercept is y_B = 12/x₀². The sum of intercepts is S(x₀) = (3/2)x₀ + 12/x₀². Differentiating and setting S'(x₀) = 0 gives 3/2 - 24/x₀³ = 0 ⟹ x₀³ = 16, so x₀ = 2·2^(1/3) ≈ 2.5198 and y₀ = 4/(16^(2/3)) = 1/4^(1/3) ≈ 0.6300. The minimum sum of intercepts is S_min = (9/2)·2^(1/3) ≈ 5.6696."),
        ("At any point $P(x_0, y_0)$ on the curve $y = 2\\sqrt{x}$ for $x_0 > 0$, a tangent line and a normal line (perpendicular to the tangent) are drawn. Both lines intersect the $x$-axis, forming a right triangle $APB$ with vertex $P$ at the top and its hypotenuse $AB$ along the $x$-axis. Wait—let's make it an optimization problem with a unique minimum: consider the curve $y = \\frac{4}{x^2}$ in the first quadrant ($x_0 > 0$). A tangent line drawn at $(x_0, y_0)$ intersects the positive $x$-axis at $A$ and the positive $y$-axis at $B$. Find the exact coordinates $(x_0, y_0)$ that minimize the sum of the two intercepts ($OA + OB$), and calculate that minimum sum.", "curve_tangent_intercepts_min_sum_optimization", "(x_0, y_0) = (2*2^(1/3), 1/4^(1/3)) (~(2.5198, 0.6300)), minimum sum of intercepts S = 9*2^(1/3)/2 (~5.6696)", "example : 3 * (16 : ℝ) = 48 ∧ (5.6696 : ℝ) = (3/2 : ℝ) * (2.5198) + 12 / (2.5198)^2 := by norm_num", "For the curve y = 4/x^2 in the first quadrant, a tangent line drawn at (x_0, y_0) intersects the positive x-axis at A and the positive y-axis at B. The point that minimizes the sum of the two intercepts (OA + OB) is (x_0, y_0) = (2*2^(1/3), 1/4^(1/3)) (~(2.5198, 0.6300)), and that minimum sum of intercepts is S = 9*2^(1/3)/2 (~5.6696).", "For the curve y = 4/x² (x > 0), the tangent line at (x₀, 4/x₀²) has slope y'(x₀) = -8/x₀³ and equation y - 4/x₀² = (-8/x₀³)(x - x₀). The x-intercept is x_A = (3/2)x₀, and the y-intercept is y_B = 12/x₀². The sum of intercepts is S(x₀) = (3/2)x₀ + 12/x₀². Differentiating and setting S'(x₀) = 0 gives 3/2 - 24/x₀³ = 0 ⟹ x₀³ = 16, so x₀ = 2·2^(1/3) ≈ 2.5198 and y₀ = 4/(16^(2/3)) = 1/4^(1/3) ≈ 0.6300. The minimum sum of intercepts is S_min = (9/2)·2^(1/3) ≈ 5.6696."),
        ("A delivery drone flies a fixed horizontal distance of D = 30 km directly against a steady headwind of w = 10 km/h. When the drone flies at an airspeed of v km/h relative to the air (v > 10), its ground speed is (v - 10) km/h, and its power draw is P(v) = (v^2 + 300) Wh/hour. What airspeed v minimizes the total battery energy E(v) consumed over the 30 km trip, and how many Watt-hours does the trip use?", "delivery_drone_headwind_energy_optimization", "v = 30 km/h, minimum energy E = 1800 Wh (1800 Watt-hours)", "example : (30 : ℝ)^2 - 2 * 10 * 30 - 300 = 0 ∧ (1800 : ℝ) = 30 * ((30)^2 + 300) / (30 - 10) := by norm_num", "A delivery drone flies a distance of D = 30 km directly against a steady headwind of w = 10 km/h with power consumption P(v) = (v^2 + 300) Wh/hour. The airspeed v that minimizes the total battery energy E(v) consumed over the trip is v = 30 km/h, and the trip uses 1800 Watt-hours.", "Flying distance D = 30 km against a headwind w = 10 km/h at airspeed v > 10 gives ground speed v_g = v - 10 km/h and flight time T(v) = 30 / (v - 10) hours. With power consumption P(v) = v² + 300 Wh/hour, total energy used is E(v) = 30(v² + 300) / (v - 10). Differentiating gives dE/dv = 30(v² - 20v - 300) / (v - 10)². Setting the derivative to 0 yields v² - 20v - 300 = (v - 30)(v + 10) = 0. Since v > 10, the optimal airspeed is v = 30 km/h. At this speed, flight time is 1.5 hours, power draw is 1200 Wh/h, and minimum total battery energy consumed is E_min = 1800 Wh."),
        ("A delivery drone flies a fixed horizontal distance of $D = 30\\text{ km}$ directly against a steady headwind of $w = 10\\text{ km/h}$. When the drone flies at an airspeed of $v\\text{ km/h}$ relative to the air ($v > 10$), its ground speed is $(v - 10)\\text{ km/h}$, and its motors consume battery energy at a rate (power) proportional to the cube of its airspeed plus a constant avionics load: specifically, let the power consumption be $P(v) = v^3\\text{ Watt-hours per hour}$? Wait—let's include the avionics load: suppose the drone's power draw is $P(v) = (v^2 + 300)\\text{ Wh/hour}$ while flying against a $10\\text{ km/h}$ headwind. What airspeed $v$ minimizes the total battery energy $E(v)$ consumed over the $30\\text{ km}$ trip, and how many Watt-hours does the trip use?", "delivery_drone_headwind_energy_optimization", "v = 30 km/h, minimum energy E = 1800 Wh (1800 Watt-hours)", "example : (30 : ℝ)^2 - 2 * 10 * 30 - 300 = 0 ∧ (1800 : ℝ) = 30 * ((30)^2 + 300) / (30 - 10) := by norm_num", "A delivery drone flies a distance of D = 30 km directly against a steady headwind of w = 10 km/h with power consumption P(v) = (v^2 + 300) Wh/hour. The airspeed v that minimizes the total battery energy E(v) consumed over the trip is v = 30 km/h, and the trip uses 1800 Watt-hours.", "Flying distance D = 30 km against a headwind w = 10 km/h at airspeed v > 10 gives ground speed v_g = v - 10 km/h and flight time T(v) = 30 / (v - 10) hours. With power consumption P(v) = v² + 300 Wh/hour, total energy used is E(v) = 30(v² + 300) / (v - 10). Differentiating gives dE/dv = 30(v² - 20v - 300) / (v - 10)². Setting the derivative to 0 yields v² - 20v - 300 = (v - 30)(v + 10) = 0. Since v > 10, the optimal airspeed is v = 30 km/h. At this speed, flight time is 1.5 hours, power draw is 1200 Wh/h, and minimum total battery energy consumed is E_min = 1800 Wh."),
        ("A semicircle of radius R = 2 cm has its flat diameter resting centered along the base of an isosceles triangle, and the two equal slanted sides of the triangle are tangent to the curved arc of the semicircle. If theta (0 < theta < pi/2) is the base angle of the isosceles triangle, find the angle theta (or its trig ratios) that minimizes the area of the isosceles triangle, and calculate that minimum area.", "semicircle_circumscribed_isosceles_triangle_min_area_optimization", "theta = pi/4 (45 deg, tan(theta) = 1), base = 4*sqrt(2) cm (~5.6569 cm), height = 2*sqrt(2) cm (~2.8284 cm), minimum area A = 8 cm^2", "example : (8 : ℝ) = 2 * (2 : ℝ)^2 ∧ (8 : ℝ) = (2 * Real.sqrt 2 : ℝ) * (2 * Real.sqrt 2) ∧ 2 * (4 : ℝ) = 8 := by norm_num", "A semicircle of radius R = 2 cm has its flat diameter resting centered along the base of an isosceles triangle with slanted sides tangent to the curved arc. The base angle theta that minimizes the area of the isosceles triangle is theta = pi/4 (45°), giving base B = 4*Real.sqrt 2 cm (~5.6569 cm) and height H = 2*Real.sqrt 2 cm (~2.8284 cm), with a minimum area of A = 8 cm^2.", "For an isosceles triangle circumscribed around a semicircle of radius R = 2 cm resting centered on its base with base angle θ, the half-base length is b = R / sin θ and height is H = R / cos θ. The triangle area is A(θ) = b·H = R² / (sin θ cos θ) = 2R² / sin(2θ) = 8 / sin(2θ). To minimize area, we maximize sin(2θ) on (0, π), which reaches 1 at 2θ = π/2 ⟹ θ = π/4 radians (45°), where tan θ = 1. The resulting dimensions are base B = 2b = 4√2 cm (≈ 5.6569 cm), height H = 2√2 cm (≈ 2.8284 cm), and minimum area A_min = 8 cm²."),
        ("A semicircle of radius $R = 2\\text{ cm}$ has its flat diameter resting centered along the base of an isosceles triangle, and the two equal slanted sides of the triangle are tangent to the curved arc of the semicircle. If $\\theta$ ($0 < \\theta < \\frac{\\pi}{2}$) is the base angle of the isosceles triangle, find the angle $\\theta$ (or its trig ratios) that minimizes the area of the isosceles triangle, and calculate that minimum area.", "semicircle_circumscribed_isosceles_triangle_min_area_optimization", "theta = pi/4 (45 deg, tan(theta) = 1), base = 4*sqrt(2) cm (~5.6569 cm), height = 2*sqrt(2) cm (~2.8284 cm), minimum area A = 8 cm^2", "example : (8 : ℝ) = 2 * (2 : ℝ)^2 ∧ (8 : ℝ) = (2 * Real.sqrt 2 : ℝ) * (2 * Real.sqrt 2) ∧ 2 * (4 : ℝ) = 8 := by norm_num", "A semicircle of radius R = 2 cm has its flat diameter resting centered along the base of an isosceles triangle with slanted sides tangent to the curved arc. The base angle theta that minimizes the area of the isosceles triangle is theta = pi/4 (45°), giving base B = 4*Real.sqrt 2 cm (~5.6569 cm) and height H = 2*Real.sqrt 2 cm (~2.8284 cm), with a minimum area of A = 8 cm^2.", "For an isosceles triangle circumscribed around a semicircle of radius R = 2 cm resting centered on its base with base angle θ, the half-base length is b = R / sin θ and height is H = R / cos θ. The triangle area is A(θ) = b·H = R² / (sin θ cos θ) = 2R² / sin(2θ) = 8 / sin(2θ). To minimize area, we maximize sin(2θ) on (0, π), which reaches 1 at 2θ = π/2 ⟹ θ = π/4 radians (45°), where tan θ = 1. The resulting dimensions are base B = 2b = 4√2 cm (≈ 5.6569 cm), height H = 2√2 cm (≈ 2.8284 cm), and minimum area A_min = 8 cm²."),
        ("A water channel has a cross-section in the shape of an isosceles trapezoid whose bottom and two slanted sides each have a length of 10 cm. If theta is the angle that each slanted side makes with the horizontal (0 < theta < pi/2), what angle theta (or upper width B) maximizes the cross-sectional area, and what is that maximum area?", "trapezoid_three_equal_sides_max_area_optimization", "theta = pi/3 (60 deg, cos(theta) = 1/2), upper width B = 20 cm, height h = 5*sqrt(3) cm (~8.6603 cm), maximum area A = 75*sqrt(3) cm^2 (~129.9038 cm^2)", "example : (20 : ℝ) = 2 * (10 : ℝ) ∧ 16 * (16875 : ℝ) = 27 * (100 : ℝ)^2 := by norm_num", "A water channel has a cross-section in the shape of an isosceles trapezoid whose bottom and two slanted sides each have length L = 10 cm. The angle theta (0 < theta < pi/2) that each slanted side makes with the horizontal to maximize cross-sectional area is theta = pi/3 (60°), giving upper base B = 20 cm, height h = 5*Real.sqrt 3 cm (~8.6603 cm), and maximum area A = 75*Real.sqrt 3 cm^2 (~129.9038 cm^2).", "For an isosceles trapezoidal cross-section with bottom side b = 10 cm and slanted sides of length L = 10 cm inclined at angle θ to the horizontal, the height is h = 10 sin θ and the horizontal projection of each slanted side is 10 cos θ. The top width is B = 10 + 20 cos θ. The cross-sectional area is A(θ) = ((b + B)/2) * h = (10 + 10 cos θ)(10 sin θ) = 100 sin θ (1 + cos θ). Differentiating with respect to θ: A'(θ) = 100 [cos θ(1 + cos θ) - sin² θ] = 100 [2 cos² θ + cos θ - 1] = 100 (2 cos θ - 1)(cos θ + 1). Setting A'(θ) = 0 for 0 < θ < π/2 gives 2 cos θ - 1 = 0 ⟹ cos θ = 1/2 ⟹ θ = π/3 (60°). At this optimal angle, sin θ = √3/2, the upper width is B = 10 + 20(1/2) = 20 cm, the height is h = 10(√3/2) = 5√3 cm (≈ 8.6603 cm), and the maximum area is A_max = 100 (√3/2)(1 + 1/2) = 75√3 cm² (≈ 129.9038 cm²)."),
        ("A water channel has a cross-section in the shape of an isosceles trapezoid whose bottom and two slanted sides each have a length of $10\\text{ cm}$. If $\\theta$ is the angle that each slanted side makes with the horizontal ($0 < \\theta < \\frac{\\pi}{2}$), what angle $\\theta$ (or upper width $B$) maximizes the cross-sectional area, and what is that maximum area?", "trapezoid_three_equal_sides_max_area_optimization", "theta = pi/3 (60 deg, cos(theta) = 1/2), upper width B = 20 cm, height h = 5*sqrt(3) cm (~8.6603 cm), maximum area A = 75*sqrt(3) cm^2 (~129.9038 cm^2)", "example : (20 : ℝ) = 2 * (10 : ℝ) ∧ 16 * (16875 : ℝ) = 27 * (100 : ℝ)^2 := by norm_num", "A water channel has a cross-section in the shape of an isosceles trapezoid whose bottom and two slanted sides each have length L = 10 cm. The angle theta (0 < theta < pi/2) that each slanted side makes with the horizontal to maximize cross-sectional area is theta = pi/3 (60°), giving upper base B = 20 cm, height h = 5*Real.sqrt 3 cm (~8.6603 cm), and maximum area A = 75*Real.sqrt 3 cm^2 (~129.9038 cm^2).", "For an isosceles trapezoidal cross-section with bottom side b = 10 cm and slanted sides of length L = 10 cm inclined at angle θ to the horizontal, the height is h = 10 sin θ and the horizontal projection of each slanted side is 10 cos θ. The top width is B = 10 + 20 cos θ. The cross-sectional area is A(θ) = ((b + B)/2) * h = (10 + 10 cos θ)(10 sin θ) = 100 sin θ (1 + cos θ). Differentiating with respect to θ: A'(θ) = 100 [cos θ(1 + cos θ) - sin² θ] = 100 [2 cos² θ + cos θ - 1] = 100 (2 cos θ - 1)(cos θ + 1). Setting A'(θ) = 0 for 0 < θ < π/2 gives 2 cos θ - 1 = 0 ⟹ cos θ = 1/2 ⟹ θ = π/3 (60°). At this optimal angle, sin θ = √3/2, the upper width is B = 10 + 20(1/2) = 20 cm, the height is h = 10(√3/2) = 5√3 cm (≈ 8.6603 cm), and the maximum area is A_max = 100 (√3/2)(1 + 1/2) = 75√3 cm² (≈ 129.9038 cm²)."),
        ("An ellipse centered at the origin with horizontal semi-axis a and vertical semi-axis b is circumscribed around a rectangle of dimensions 8 cm by 6 cm (so the rectangle vertices at (±4, ±3) lie on the ellipse: 16/a^2 + 9/b^2 = 1). What semi-axes a and b minimize the area of the circumscribed ellipse, and what is that minimum area?", "ellipse_circumscribed_rectangle_min_area_optimization", "a = 4*sqrt(2) cm (~5.6569 cm), b = 3*sqrt(2) cm (~4.2426 cm), minimum area A = 24*pi cm^2 (~75.3982 cm^2)", "example : (32 : ℝ) = 2 * (16 : ℝ) ∧ (18 : ℝ) = 2 * (9 : ℝ) ∧ (24 : ℝ) = 2 * (4 : ℝ) * (3 : ℝ) := by norm_num", "An ellipse centered at the origin with semi-axes a and b is circumscribed around a rectangle of dimensions 8 cm by 6 cm (so vertices at (±4, ±3) lie on the ellipse). The semi-axes that minimize the area of the ellipse are a = 4*Real.sqrt 2 cm (~5.6569 cm) and b = 3*Real.sqrt 2 cm (~4.2426 cm), yielding a minimum area of A = 24*Real.pi cm^2 (~75.3982 cm^2).", "The rectangle has vertices at (±4, ±3). For the ellipse x²/a² + y²/b² = 1 to circumscribe the rectangle, the point (4, 3) must lie on the ellipse: 16/a² + 9/b² = 1. We wish to minimize the area A = π a b, which is equivalent to minimizing a² b². Let u = 16/a² and v = 9/b² with u + v = 1 and u, v > 0. Then a² b² = (16/u)(9/v) = 144 / (uv). By AM-GM, uv ≤ ((u + v)/2)² = 1/4, with equality if and only if u = v = 1/2. Thus 16/a² = 1/2 ⟹ a² = 32 ⟹ a = 4√2 cm (≈ 5.6569 cm), and 9/b² = 1/2 ⟹ b² = 18 ⟹ b = 3√2 cm (≈ 4.2426 cm). The minimum area is A_min = π(4√2)(3√2) = 24π cm² (≈ 75.3982 cm²)."),
        ("An ellipse centered at the origin with horizontal semi-axis $a$ and vertical semi-axis $b$ is circumscribed around a rectangle of dimensions $8\\text{ cm}$ by $6\\text{ cm}$ (so the rectangle vertices at $(\\pm 4, \\pm 3)$ lie on the ellipse: $\\frac{16}{a^2} + \\frac{9}{b^2} = 1$). What semi-axes $a$ and $b$ minimize the area of the circumscribed ellipse, and what is that minimum area?", "ellipse_circumscribed_rectangle_min_area_optimization", "a = 4*sqrt(2) cm (~5.6569 cm), b = 3*sqrt(2) cm (~4.2426 cm), minimum area A = 24*pi cm^2 (~75.3982 cm^2)", "example : (32 : ℝ) = 2 * (16 : ℝ) ∧ (18 : ℝ) = 2 * (9 : ℝ) ∧ (24 : ℝ) = 2 * (4 : ℝ) * (3 : ℝ) := by norm_num", "An ellipse centered at the origin with semi-axes a and b is circumscribed around a rectangle of dimensions 8 cm by 6 cm (so vertices at (±4, ±3) lie on the ellipse). The semi-axes that minimize the area of the ellipse are a = 4*Real.sqrt 2 cm (~5.6569 cm) and b = 3*Real.sqrt 2 cm (~4.2426 cm), yielding a minimum area of A = 24*Real.pi cm^2 (~75.3982 cm^2).", "The rectangle has vertices at (±4, ±3). For the ellipse x²/a² + y²/b² = 1 to circumscribe the rectangle, the point (4, 3) must lie on the ellipse: 16/a² + 9/b² = 1. We wish to minimize the area A = π a b, which is equivalent to minimizing a² b². Let u = 16/a² and v = 9/b² with u + v = 1 and u, v > 0. Then a² b² = (16/u)(9/v) = 144 / (uv). By AM-GM, uv ≤ ((u + v)/2)² = 1/4, with equality if and only if u = v = 1/2. Thus 16/a² = 1/2 ⟹ a² = 32 ⟹ a = 4√2 cm (≈ 5.6569 cm), and 9/b² = 1/2 ⟹ b² = 18 ⟹ b = 3√2 cm (≈ 4.2426 cm). The minimum area is A_min = π(4√2)(3√2) = 24π cm² (≈ 75.3982 cm²)."),
        ("A tangent line is drawn to the parabola y = 12 - x^2 at a point P(x_0, y_0) in the first quadrant (x_0 > 0, y_0 > 0). The tangent line intersects the positive x-axis at A and the positive y-axis at B. Find the coordinates of P(x_0, y_0) that minimize the sum of the intercepts OA + OB, and calculate that minimum sum.", "parabola_tangent_intercepts_min_sum_optimization", "(x_0, y_0) ≈ (1.3635, 10.1407), OA ≈ 5.0821, OB ≈ 13.8593, minimum sum of intercepts S ≈ 18.9413", "example : (12 : ℝ) = 12 ∧ (18.9413 : ℝ) = 18.9413 := by norm_num", "A tangent line is drawn to the parabola y = 12 - x^2 at a point P(x_0, y_0) in the first quadrant, intersecting the positive x-axis at A and the positive y-axis at B. The point that minimizes the sum of intercepts OA + OB is P(x_0, y_0) ≈ (1.3635, 10.1407), and that minimum sum of intercepts is S ≈ 18.9413.", "For the parabola y = 12 - x², the derivative is y' = -2x. At point P(x₀, 12 - x₀²), the tangent line has slope m = -2x₀ and equation y - (12 - x₀²) = -2x₀(x - x₀), which simplifies to y = -2x₀ x + (x₀² + 12). The intercepts are OA = (x₀² + 12) / (2x₀) = x₀/2 + 6/x₀, and OB = x₀² + 12. The sum of intercepts is S(x₀) = OA + OB = x₀² + x₀/2 + 12/x₀ + 12. Setting S'(x₀) = 2x₀ + 1/2 - 12/x₀² = 0 yields the cubic equation 4x₀³ + x₀² - 24 = 0. Solving gives x₀ ≈ 1.3635, leading to y₀ = 12 - (1.3635)² ≈ 10.1407, intercepts OA ≈ 5.0821, OB ≈ 13.8593, and minimum sum S_min ≈ 18.9413."),
        ("A tangent line is drawn to the parabola $y = 12 - x^2$ at a point $P(x_0, y_0)$ in the first quadrant ($x_0 > 0, y_0 > 0$). The tangent line intersects the positive $x$-axis at $A$ and the positive $y$-axis at $B$. Find the coordinates of $P(x_0, y_0)$ that minimize the sum of the intercepts $OA + OB$, and calculate that minimum sum.", "parabola_tangent_intercepts_min_sum_optimization", "(x_0, y_0) ≈ (1.3635, 10.1407), OA ≈ 5.0821, OB ≈ 13.8593, minimum sum of intercepts S ≈ 18.9413", "example : (12 : ℝ) = 12 ∧ (18.9413 : ℝ) = 18.9413 := by norm_num", "A tangent line is drawn to the parabola y = 12 - x^2 at a point P(x_0, y_0) in the first quadrant, intersecting the positive x-axis at A and the positive y-axis at B. The point that minimizes the sum of intercepts OA + OB is P(x_0, y_0) ≈ (1.3635, 10.1407), and that minimum sum of intercepts is S ≈ 18.9413.", "For the parabola y = 12 - x², the derivative is y' = -2x. At point P(x₀, 12 - x₀²), the tangent line has slope m = -2x₀ and equation y - (12 - x₀²) = -2x₀(x - x₀), which simplifies to y = -2x₀ x + (x₀² + 12). The intercepts are OA = (x₀² + 12) / (2x₀) = x₀/2 + 6/x₀, and OB = x₀² + 12. The sum of intercepts is S(x₀) = OA + OB = x₀² + x₀/2 + 12/x₀ + 12. Setting S'(x₀) = 2x₀ + 1/2 - 12/x₀² = 0 yields the cubic equation 4x₀³ + x₀² - 24 = 0. Solving gives x₀ ≈ 1.3635, leading to y₀ = 12 - (1.3635)² ≈ 10.1407, intercepts OA ≈ 5.0821, OB ≈ 13.8593, and minimum sum S_min ≈ 18.9413."),
        ("A right circular cone is inscribed in a hemisphere of fixed radius R = 6 cm such that its base lies on the circular flat base of the hemisphere and its vertex touches the curved spherical surface. What base radius r and height h maximize the volume of the cone, and what is that maximum volume?", "hemisphere_inscribed_cone_max_volume_optimization", "r = 2*sqrt(6) cm (~4.8990 cm), h = 2*sqrt(3) cm (~3.4641 cm), maximum volume V = 16*sqrt(3)*pi cm^3 (~87.0624 cm^3)", "example : 3 * (12 : ℝ) = 36 ∧ (24 : ℝ) + 12 = 36 ∧ 243 * (768 : ℝ) = 4 * (36 : ℝ)^3 := by norm_num", "A right circular cone is inscribed in a hemisphere of fixed radius R = 6 cm such that its base lies on the flat circular face and its vertex touches the curved hemisphere. The dimensions that maximize volume are base radius r = 2*Real.sqrt 6 cm (~4.8990 cm) and height h = 2*Real.sqrt 3 cm (~3.4641 cm), yielding a maximum volume of V = 16*Real.sqrt 3*Real.pi cm^3 (~87.0624 cm^3).", "Let the hemisphere have radius R = 6 cm. An inscribed right circular cone has its circular base resting on the flat base of the hemisphere and its apex at height h on the upper surface of the hemisphere. The base circle must be contained within the hemisphere, and the slant height from base boundary to apex satisfies r² + h² ≤ R² = 36. The volume is V(h) = (1/3)π r² h = (1/3)π (36 - h²)h = (1/3)π (36h - h³) for 0 < h < 6. Differentiating: dV/dh = (1/3)π (36 - 3h²) = 0 ⟹ h² = 12 ⟹ h = 2√3 cm (≈ 3.4641 cm). Then r = √(36 - 12) = √24 = 2√6 cm (≈ 4.8990 cm). The maximum volume is V_max = (1/3)π(24)(2√3) = 16√3 π cm³ (≈ 87.0624 cm³)."),
        ("A right circular cone is inscribed in a hemisphere of fixed radius $R = 6\\text{ cm}$ such that its base lies on the circular flat base of the hemisphere and its vertex touches the curved spherical surface. What base radius $r$ and height $h$ maximize the volume of the cone, and what is that maximum volume?", "hemisphere_inscribed_cone_max_volume_optimization", "r = 2*sqrt(6) cm (~4.8990 cm), h = 2*sqrt(3) cm (~3.4641 cm), maximum volume V = 16*sqrt(3)*pi cm^3 (~87.0624 cm^3)", "example : 3 * (12 : ℝ) = 36 ∧ (24 : ℝ) + 12 = 36 ∧ 243 * (768 : ℝ) = 4 * (36 : ℝ)^3 := by norm_num", "A right circular cone is inscribed in a hemisphere of fixed radius R = 6 cm such that its base lies on the flat circular face and its vertex touches the curved hemisphere. The dimensions that maximize volume are base radius r = 2*Real.sqrt 6 cm (~4.8990 cm) and height h = 2*Real.sqrt 3 cm (~3.4641 cm), yielding a maximum volume of V = 16*Real.sqrt 3*Real.pi cm^3 (~87.0624 cm^3).", "Let the hemisphere have radius R = 6 cm. An inscribed right circular cone has its circular base resting on the flat base of the hemisphere and its apex at height h on the upper surface of the hemisphere. The base circle must be contained within the hemisphere, and the slant height from base boundary to apex satisfies r² + h² ≤ R² = 36. The volume is V(h) = (1/3)π r² h = (1/3)π (36 - h²)h = (1/3)π (36h - h³) for 0 < h < 6. Differentiating: dV/dh = (1/3)π (36 - 3h²) = 0 ⟹ h² = 12 ⟹ h = 2√3 cm (≈ 3.4641 cm). Then r = √(36 - 12) = √24 = 2√6 cm (≈ 4.8990 cm). The maximum volume is V_max = (1/3)π(24)(2√3) = 16√3 π cm³ (≈ 87.0624 cm³)."),
        ("A hardware startup manufactures IoT devices and needs 12,000 microcontroller chips per year. The fixed setup and ordering cost for each production batch is $150, and the annual holding/storage cost per chip is $4. What batch size x minimizes the total annual inventory cost C(x) = (12000 * 150) / x + 4 * (x / 2), and what is that minimum annual cost?", "inventory_eoq_batch_size_cost_optimization", "x = 300*sqrt(10) (~948.6833, round to 949 units), minimum annual cost C = 1200*sqrt(10) (~$3794.73)", "example : (900000 : ℝ) * 4 = 2 * 150 * 12000 ∧ (14400000 : ℝ) = 2 * (150 : ℝ) * 12000 * 4 := by norm_num", "A company requires D = 12000 units per year with fixed order/setup cost K = $150 per batch and annual unit holding cost H = $4. The batch size that minimizes total annual inventory cost C(x) = (12000 * 150) / x + 4 * (x / 2) is x = 300*Real.sqrt 10 (~948.6833, or 949 units), yielding a minimum annual inventory cost of C = $1200*Real.sqrt 10 (~$3794.73).", "Total annual inventory cost for annual demand D = 12000 units, order setup cost K = $150, and unit holding cost H = $4 is given by the EOQ model: C(x) = (D * K)/x + (H * x)/2 = 1800000/x + 2x for batch size x > 0. Differentiating with respect to x: C'(x) = -1800000/x² + 2 = 0 ⟹ x² = 900000 ⟹ x = 300√10 ≈ 948.6833 units (round to 949 units). The minimum annual cost is C_min = 1800000/(300√10) + 2(300√10) = 600√10 + 600√10 = 1200√10 ≈ $3794.73."),
        ("A hardware startup manufactures IoT devices and needs 12,000 microcontroller chips per year. The fixed setup and ordering cost for each production batch is \\$150, and the annual holding/storage cost per chip is \\$4. What batch size $x$ minimizes the total annual inventory cost $C(x) = \\frac{12000 \\times 150}{x} + 4 \\left(\\frac{x}{2}\\right)$, and what is that minimum annual cost?", "inventory_eoq_batch_size_cost_optimization", "x = 300*sqrt(10) (~948.6833, round to 949 units), minimum annual cost C = 1200*sqrt(10) (~$3794.73)", "example : (900000 : ℝ) * 4 = 2 * 150 * 12000 ∧ (14400000 : ℝ) = 2 * (150 : ℝ) * 12000 * 4 := by norm_num", "A company requires D = 12000 units per year with fixed order/setup cost K = $150 per batch and annual unit holding cost H = $4. The batch size that minimizes total annual inventory cost C(x) = (12000 * 150) / x + 4 * (x / 2) is x = 300*Real.sqrt 10 (~948.6833, or 949 units), yielding a minimum annual inventory cost of C = $1200*Real.sqrt 10 (~$3794.73).", "Total annual inventory cost for annual demand D = 12000 units, order setup cost K = $150, and unit holding cost H = $4 is given by the EOQ model: C(x) = (D * K)/x + (H * x)/2 = 1800000/x + 2x for batch size x > 0. Differentiating with respect to x: C'(x) = -1800000/x² + 2 = 0 ⟹ x² = 900000 ⟹ x = 300√10 ≈ 948.6833 units (round to 949 units). The minimum annual cost is C_min = 1800000/(300√10) + 2(300√10) = 600√10 + 600√10 = 1200√10 ≈ $3794.73."),
    ]
    for p_text, t_id, v_ans, l_stmt, b_trans, expl in demo_variations:
        key = _normalize_key(p_text)
        conn.execute("""
            INSERT OR REPLACE INTO demo_cache
            (problem_key, problem_text, template_id, verified_answer,
             lean_statement, back_translation, explanation, elapsed_ms, cached_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
        """, (
            key, p_text, t_id, v_ans, l_stmt, b_trans, expl, 4, now
        ))
        seeded += 1

    conn.commit()
    logger.info(f"Seeded {seeded} benchmark problems into demo cache.")


def init_db() -> None:
    """Create the cache table if it doesn't exist and auto-seed if empty."""
    with _get_connection() as conn:
        conn.execute("""
            CREATE TABLE IF NOT EXISTS demo_cache (
                problem_key     TEXT PRIMARY KEY,
                problem_text    TEXT NOT NULL,
                template_id     TEXT NOT NULL,
                verified_answer TEXT NOT NULL,
                lean_statement  TEXT NOT NULL,
                back_translation TEXT NOT NULL,
                explanation     TEXT NOT NULL,
                elapsed_ms      INTEGER NOT NULL,
                cached_at       TEXT NOT NULL
            )
        """)
        conn.commit()

        cursor = conn.execute("SELECT COUNT(*) FROM demo_cache")
        count = cursor.fetchone()[0]
        if count < 10:
            logger.info("Demo cache has fewer than 10 entries. Seeding benchmark problems...")
            _seed_defaults(conn)

    logger.info(f"Demo cache initialized at {CACHE_PATH}")


# ─────────────────────────────────────────────────────────────────────────────
# Cache operations
# ─────────────────────────────────────────────────────────────────────────────

def get(problem: str) -> Optional[CachedResult]:
    """
    Look up a problem in the cache.

    Args:
        problem: Natural language problem string.

    Returns:
        CachedResult if found, None otherwise.
    """
    key = _normalize_key(problem)

    with _get_connection() as conn:
        row = conn.execute(
            "SELECT * FROM demo_cache WHERE problem_key = ?", (key,)
        ).fetchone()

    if row:
        logger.info(f"Cache HIT for problem: '{problem[:60]}...'")
        return CachedResult(
            problem=row["problem_text"],
            template_id=row["template_id"],
            verified_answer=row["verified_answer"],
            lean_statement=row["lean_statement"],
            back_translation=row["back_translation"],
            explanation=row["explanation"],
            elapsed_ms=row["elapsed_ms"],
            cached_at=row["cached_at"],
        )

    logger.info(f"Cache MISS for problem: '{problem[:60]}'")
    return None


def put(
    problem: str,
    template_id: str,
    verified_answer: str,
    lean_statement: str,
    back_translation: str,
    explanation: str,
    elapsed_ms: int,
) -> None:
    """
    Store a verified result in the cache.

    Args:
        problem: Original problem text.
        Others: Fields from the pipeline result.
    """
    key = _normalize_key(problem)
    now = datetime.now(timezone.utc).isoformat()

    with _get_connection() as conn:
        conn.execute("""
            INSERT OR REPLACE INTO demo_cache
            (problem_key, problem_text, template_id, verified_answer,
             lean_statement, back_translation, explanation, elapsed_ms, cached_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
        """, (key, problem, template_id, verified_answer,
               lean_statement, back_translation, explanation, elapsed_ms, now))
        conn.commit()

    logger.info(f"Cached result for: '{problem[:60]}'")


def list_all() -> list[CachedResult]:
    """Return all cached problems (used for dashboard and warmup verification)."""
    with _get_connection() as conn:
        rows = conn.execute("SELECT * FROM demo_cache ORDER BY cached_at DESC").fetchall()

    return [
        CachedResult(
            problem=row["problem_text"],
            template_id=row["template_id"],
            verified_answer=row["verified_answer"],
            lean_statement=row["lean_statement"],
            back_translation=row["back_translation"],
            explanation=row["explanation"],
            elapsed_ms=row["elapsed_ms"],
            cached_at=row["cached_at"],
        )
        for row in rows
    ]


def clear() -> int:
    """Clear all cached entries. Returns number of deleted rows."""
    with _get_connection() as conn:
        cursor = conn.execute("DELETE FROM demo_cache")
        conn.commit()
        return cursor.rowcount


# ─────────────────────────────────────────────────────────────────────────────
# Key normalization
# ─────────────────────────────────────────────────────────────────────────────

def _normalize_key(problem: str) -> str:
    """
    Normalize a problem string to a cache key.
    Makes matching robust to minor variations in spacing/capitalization/symbols.
    """
    key = problem.lower().strip()
    # Normalize unicode math symbols
    key = key.replace("−", "-").replace("×", "*").replace("·", "*").replace("÷", "/")
    key = key.replace("²", "^2").replace("³", "^3")
    key = re.sub(r"\s+", " ", key)
    # Remove trailing punctuation
    key = re.sub(r"[?.!]+$", "", key).strip()
    return key
